import { schema, table, t, SenderError, Router, SyncResponse, type InferSchema, type ReducerCtx } from 'spacetimedb/server';
import { ScheduleAt, Timestamp, TimeDuration, Identity } from 'spacetimedb';
// Receiver bindings for the second database (module/library), generated by `npm run generate:library`.
import library from './remote_bindings/library/index';
import { verifyElevenLabs } from './sha256';
// Official SpacetimeDB module (spacetimedb.com/modules), mounted as a submodule: per-sender quotas for set events.
import * as rateLimit from '@spacetimedb/rate-limit/submodule';

// One camera or person placement. f35 is the 35 mm-equivalent focal length (diagonal convention, see CONTRACTS.md).
const Pose = t.object('Pose', {
  lat: t.f64(), lon: t.f64(), alt: t.f64(),
  heading: t.f64(), pitch: t.f64(), roll: t.f64(),
  f35: t.f64(),
});

const config = table({ name: 'config' }, {
  id: t.u32().primaryKey(),
  owner: t.identity(),
  crew: t.option(t.identity()),
  crewCode: t.string(),
});

const spot = table({ name: 'spot', public: true }, {
  id: t.string().primaryKey(),
  name: t.string(),
  lat: t.f64(), lon: t.f64(), radiusM: t.f64(),
  cameras: t.u32(),
  modelVersion: t.string(),
});

const session = table({ name: 'session', public: true }, {
  id: t.u64().primaryKey().autoInc(),
  code: t.string().unique(),
  spotId: t.string(),
  title: t.string(),
  owner: t.identity().index('btree'),
  planTime: t.option(t.timestamp()),
  createdAt: t.timestamp(),
});

// The single-column session_id index is what the row-level-security joins and the my_sessions view join on;
// the online index feeds the live_sessions view (views may only read through indexes).
const participant = table({ name: 'participant', public: true, indexes: [
  { accessor: 'by_session_identity', algorithm: 'btree', columns: ['sessionId', 'identity'] },
  { accessor: 'by_online', algorithm: 'btree', columns: ['online'] },
] }, {
  id: t.u64().primaryKey().autoInc(),
  sessionId: t.u64().index('btree'),
  identity: t.identity().index('btree'),
  name: t.string(),
  role: t.string(), // planner | scout | crew
  online: t.bool(),
  lastSeen: t.timestamp(),
});

const photo = table({ name: 'photo', public: true }, {
  id: t.u64().primaryKey().autoInc(),
  sessionId: t.u64().index('btree'),
  owner: t.identity(),
  url: t.string(),
  thumb: t.string(), // small JPEG data URL so every client can draw it without a second fetch
  width: t.u32(), height: t.u32(),
  pinLat: t.option(t.f64()), pinLon: t.option(t.f64()),
  exifF35: t.option(t.f64()),
  source: t.string(), // web | imessage | telegram
  createdAt: t.timestamp(),
});

const solveJob = table({ name: 'solve_job', public: true }, {
  id: t.u64().primaryKey().autoInc(),
  photoId: t.u64().index('btree'),
  sessionId: t.u64().index('btree'),
  spotId: t.string(),
  state: t.string().index('btree'), // queued | running | done | failed
  progress: t.string(),
  worker: t.option(t.identity()),
  leaseUntil: t.option(t.timestamp()),
  attempts: t.u32(),
  error: t.string(),
  lensHintF35: t.option(t.f64()), // a user's "it was about 85 mm" on a re-run; the solver treats it as a range
  createdAt: t.timestamp(),
});

const solveResult = table({ name: 'solve_result', public: true }, {
  photoId: t.u64().primaryKey(),
  sessionId: t.u64().index('btree'),
  jobId: t.u64(),
  pose: Pose,
  inliers: t.u32(),
  confidence: t.string(), // solid | check | none
  reason: t.string(),
  lensReadF35: t.option(t.f64()),
  secs: t.f64(),
  createdAt: t.timestamp(),
});

const camera = table({ name: 'camera', public: true }, {
  sessionId: t.u64().primaryKey(),
  pose: Pose,
  updatedBy: t.identity(),
});

const person = table({ name: 'person', public: true }, {
  id: t.u64().primaryKey().autoInc(),
  sessionId: t.u64().index('btree'),
  lat: t.f64(), lon: t.f64(), heading: t.f64(),
  label: t.string(),
  pose: t.string().default('stand'), // stand | walk | sit | lean | point | jump
  heightM: t.f64().default(1.7),
});

const devicePose = table({ name: 'device_pose', public: true }, {
  participantId: t.u64().primaryKey(),
  sessionId: t.u64().index('btree'),
  lat: t.f64(), lon: t.f64(), accuracyM: t.f64(), heading: t.option(t.f64()),
  at: t.timestamp(),
});

const previewJob = table({ name: 'preview_job', public: true }, {
  id: t.u64().primaryKey().autoInc(),
  sessionId: t.u64().index('btree'),
  photoId: t.u64(),
  instruction: t.string(),
  f35: t.option(t.f64()),
  people: t.u32(),
  sunAzimuth: t.option(t.f64()), sunAltitude: t.option(t.f64()),
  state: t.string().index('btree'),
  imageUrl: t.string(),
  error: t.string(),
  worker: t.option(t.identity()),
  leaseUntil: t.option(t.timestamp()),
  attempts: t.u32(),
  createdAt: t.timestamp(),
  // Appended with defaults so existing rows migrate in place. 'render' rows are the studio's AI render pass:
  // the crew creates them already running (startRender) and finds its row again by requestId.
  kind: t.string().default('preview'), // preview | render
  requestId: t.string().default(''),
});

const message = table({ name: 'message', public: true }, {
  id: t.u64().primaryKey().autoInc(),
  sessionId: t.u64().index('btree'),
  channel: t.string(), // imessage | telegram | voice | web
  threadId: t.string(),
  externalId: t.string(),
  parentExternalId: t.string(),
  direction: t.string(), // in | out
  author: t.string(),
  text: t.string(),
  imageUrl: t.string(),
  createdAt: t.timestamp(),
});

const agentStep = table({ name: 'agent_step', public: true }, {
  id: t.u64().primaryKey().autoInc(),
  sessionId: t.u64().index('btree'),
  tool: t.string(),
  args: t.string(),
  result: t.string(),
  ms: t.u32(),
  at: t.timestamp(),
});

// The studio's shared camera settings: one row per session, edited live by every planner.
const shotSettings = table({ name: 'shot_settings', public: true }, {
  sessionId: t.u64().primaryKey(),
  bodyId: t.string(),       // sensor/body id from web/src/studio/catalog
  lensId: t.string(),       // lens id from the catalog
  focalMm: t.f64(),         // actual focal length on that body (not 35 mm equivalent)
  aperture: t.f64(),        // f-number
  shutterS: t.f64(),        // seconds
  iso: t.u32(),
  whiteBalanceK: t.u32(),
  focusM: t.f64(),          // focus distance in metres
  aspect: t.string(),       // 3:2 | 4:3 | 4:5 | 1:1 | 16:9 | 65:24
  overlays: t.string(),     // comma list: thirds,golden,center,horizon,safe
  distortion: t.bool(),     // render the lens profile's distortion in the viewport
  updatedBy: t.identity(),
});

// The virtual set: every object in the shared 3D scene. Positions are metres in the session's local
// east-north-up frame centred on the spot (spot.lat/lon at ground level), so every client agrees.
const sceneObject = table({ name: 'scene_object', public: true }, {
  id: t.u64().primaryKey().autoInc(),
  sessionId: t.u64().index('btree'),
  kind: t.string(),      // model | person | light | camera | prop_generated | text
  assetId: t.string(),   // catalog id, or a /asset/<file>.glb URL for generated props
  name: t.string(),
  x: t.f64(), y: t.f64(), z: t.f64(),           // east, north, up (m)
  qx: t.f64(), qy: t.f64(), qz: t.f64(), qw: t.f64(),
  scale: t.f64(),
  color: t.string(),     // hex, for lights and tinting
  intensity: t.f64(),    // lights: lux or candela per lightType; others 0
  lightType: t.string(), // sun | point | spot | area | ''
  params: t.string(),    // small key=value;key=value list for kind-specific settings (pose, focal, aperture)
  visible: t.bool(),
  lockedBy: t.option(t.identity()), // the editor holding the gizmo, so two people don't drag one object
  updatedBy: t.identity(),
  updatedAt: t.timestamp(),
});

// Toasts every client in the session sees once: "solve finished", "scout reached the spot".
// Event tables can't be the lookup side of a filter join, so each event row is addressed to one recipient
// (one row per session member) and the filter is a plain `recipient = :sender`.
const toast = table({ name: 'toast', public: true, event: true }, {
  sessionId: t.u64(),
  kind: t.string(),
  text: t.string(),
  recipient: t.identity().default(Identity.zero()),
});

// Golden-hour reminders: the schedule fires inside the database; the crew delivers the outbox row to the session's text thread.
const reminder = table({ name: 'reminder', public: true }, {
  scheduledId: t.u64().primaryKey().autoInc(),
  scheduledAt: t.scheduleAt(),
  sessionId: t.u64().index('btree'),
  text: t.string(),
});

const outbox = table({ name: 'outbox', public: true }, {
  id: t.u64().primaryKey().autoInc(),
  sessionId: t.u64().index('btree'),
  text: t.string(),
  state: t.string().index('btree'), // pending | sent | failed
  createdAt: t.timestamp(),
});

const sweepTimer = table({ name: 'sweep_timer' }, {
  scheduledId: t.u64().primaryKey().autoInc(),
  scheduledAt: t.scheduleAt(),
});

// Who may read a session's rows: every participant, plus the crew identity in every session. Each row-level-security
// filter joins this table on an indexed session_id. Maincloud refuses a filter that joins a table which has filters
// of its own ("Subscriptions require indexes on join columns", reproduced in a lab database), and filters may only
// read public tables, so this table is public and unfiltered. It holds only numeric session ids and anonymous
// identities: no names, codes or content.
const sessionMember = table({ name: 'session_member', public: true }, {
  id: t.u64().primaryKey().autoInc(),
  sessionId: t.u64().index('btree'),
  identity: t.identity().index('btree'),
  role: t.string(), // member | crew
});

// Who is in the set right now and what they have selected. Clients heartbeat every 10 s; presence_sweep marks a
// silent editor idle after 30 s (and frees the gizmo locks they hold) and drops the row after 2 minutes.
const presence = table({ name: 'presence', public: true }, {
  participantId: t.u64().primaryKey(),
  sessionId: t.u64().index('btree'),
  identity: t.identity(),
  name: t.string(),
  color: t.string(),
  status: t.string(),          // active | idle
  focusObjectId: t.u64(),      // the scene_object they have selected, 0 for none
  at: t.timestamp(),
});
const presenceTimer = table({ name: 'presence_timer' }, {
  scheduledId: t.u64().primaryKey().autoInc(),
  scheduledAt: t.scheduleAt(),
});

// Ephemeral collaboration in the 3D set, never stored: cursors, laser-pointer pings, camera views and follow requests.
const setEvent = table({ name: 'set_event', public: true, event: true }, {
  recipient: t.identity(),
  sessionId: t.u64(),
  from: t.identity(),
  name: t.string(),
  color: t.string(),
  kind: t.string(),                 // cursor | ping | view | follow | unfollow
  x: t.f64(), y: t.f64(), z: t.f64(),     // cursor and ping: the point in the set; view: the camera eye (ENU metres)
  tx: t.f64(), ty: t.f64(), tz: t.f64(),  // view: the point the camera looks at
  objectId: t.u64(),                      // ping on an object, 0 for none
  target: t.option(t.identity()),         // follow: whom to follow; none means "follow me"
});

// One event per reducer call in a session, so the Live data inspector can name other people's calls
// (clients only learn the reducer name for their own calls).
const activity = table({ name: 'activity', public: true, event: true }, {
  recipient: t.identity(),
  sessionId: t.u64(),
  reducer: t.string(),
  who: t.string(),
  detail: t.string(),
});

// Scene history: one row per add, edit (a drag folds into one row), delete, undo and restore, with the object's
// state before and after as JSON. Undo by anyone, and restore the whole set to any point.
const sceneChange = table({ name: 'scene_change', public: true }, {
  id: t.u64().primaryKey().autoInc(),
  sessionId: t.u64().index('btree'),
  objectId: t.u64(),
  action: t.string(),   // add | update | delete | undo | restore
  before: t.string(),   // '' when the object did not exist
  after: t.string(),    // '' when the object was deleted
  by: t.identity(),
  byName: t.string(),
  at: t.timestamp(),
});
const lastChange = table({ name: 'last_change' }, {
  objectId: t.u64().primaryKey(),
  changeId: t.u64(),
});

// Live sun: while a session has a row here, sun_tick advances session.planTime (the set's clock) every second.
// rate 1 follows the real clock; rate 60 plays a minute of light per second.
const sunClock = table({ name: 'sun_clock', public: true }, {
  scheduledId: t.u64().primaryKey().autoInc(),
  scheduledAt: t.scheduleAt(),
  sessionId: t.u64().unique(),
  rate: t.f64(),
  startedBy: t.string(),
});

// One-shot schedule for the title_session procedure (Nemotron 3.5 Lightning names a shoot once its photo is placed).
const titleJob = table({ name: 'title_job' }, {
  scheduledId: t.u64().primaryKey().autoInc(),
  scheduledAt: t.scheduleAt(),
  sessionId: t.u64(),
});

// Inter-database communication with shotmatch-library. library_link holds the library's database identity, typed
// with the receiver bindings so only it can be an outbox target.
const libraryLink = table({ name: 'library_link' }, {
  id: t.u32().primaryKey(),
  db: library.identity(),
});
const publishPropOutbox = table({ name: 'publish_prop_outbox', outbox: { receiver: library.reducers.publishProp } }, {
  msgId: t.u64().primaryKey().autoInc(),
  target: library.identity().target(),
  assetUrl: t.string(),
  name: t.string(),
  prompt: t.string(),
  sessionId: t.u64(), // not sent; the onResult reducer reads it
});
const publishShotOutbox = table({ name: 'publish_shot_outbox', outbox: { receiver: library.reducers.publishShot } }, {
  msgId: t.u64().primaryKey().autoInc(),
  target: library.identity().target(),
  shareCode: t.string(), title: t.string(), spotId: t.string(), imageUrl: t.string(),
  lat: t.f64(), lon: t.f64(), heading: t.f64(), pitch: t.f64(), f35: t.f64(),
  sessionId: t.u64(), // not sent
});
// What the library accepted, mirrored here by the onResult reducers and served through anonymous views.
const libraryProp = table({ name: 'library_prop' }, {
  assetUrl: t.string().primaryKey(),
  name: t.string(),
  prompt: t.string(),
  fromSessionId: t.u64(),
  publishedAt: t.timestamp(),
});
const publicShot = table({ name: 'public_shot' }, {
  shareCode: t.string().primaryKey(),
  sessionId: t.u64().index('btree'),
  title: t.string(), spotId: t.string(), imageUrl: t.string(),
  lat: t.f64(), lon: t.f64(), heading: t.f64(), pitch: t.f64(), f35: t.f64(),
  state: t.string().index('btree'), // pending | published | failed
  error: t.string(),
  createdAt: t.timestamp(),
});

// ElevenLabs post-call webhooks the HTTP handler accepted, keyed by conversation so a retried delivery is a no-op.
// Photon: how each person in a session is reached outside the browser (an iMessage handle, a phone number, an email).
// Session data under the same row-level security, so only the session's members and the crew see an address.
const channelLink = table({ name: 'channel_link', public: true }, {
  id: t.u64().primaryKey().autoInc(),
  sessionId: t.u64().index('btree'),
  participantId: t.u64(),
  identity: t.identity(),
  channel: t.string(),   // imessage | telegram | sms | whatsapp | email | voice
  address: t.string(),   // phone number, handle or email
  verified: t.bool(),
  createdAt: t.timestamp(),
  // Appended: the person's name, so an invitee who has no SpacetimeDB identity yet (participantId 0) still has one.
  name: t.string().default(''),
});

// Photon: a text thread as a version tree. Each version points at a scene_change id, so the set at that version is
// exactly what scene history rebuilds; restoreToVersion forks a new branch from any version.
const shotVersion = table({ name: 'shot_version', public: true }, {
  id: t.u64().primaryKey().autoInc(),
  sessionId: t.u64().index('btree'),
  parentVersionId: t.option(t.u64()),
  label: t.string(),             // v3, or v3.1 for the first branch forked from v3
  externalMessageId: t.string(), // the Photon message that produced or asked for it
  channel: t.string(),
  sceneChangeId: t.u64(),        // the set as it was right after this scene_change (0 = empty set)
  imageUrl: t.string(),
  createdAt: t.timestamp(),
});

// Photon: a scout's check-in photo from the mark, scored by the crew against the planned camera.
const checkin = table({ name: 'checkin', public: true }, {
  id: t.u64().primaryKey().autoInc(),
  sessionId: t.u64().index('btree'),
  participantId: t.u64(),
  photoId: t.u64(),
  distanceM: t.f64(),
  headingErrDeg: t.f64(),
  verdict: t.string(),
  createdAt: t.timestamp(),
  // Appended: where the solver put the check-in photo (ENU metres like scene_object) and which way it faced, the photo,
  // and the scout's name (a scout only on iMessage has participantId 0).
  x: t.f64().default(0), y: t.f64().default(0), heading: t.f64().default(0),
  imageUrl: t.string().default(''),
  name: t.string().default(''),
});

// Geo layers (the geo thread): one row per (spotId, layer), refreshed in place by the refresh_layers procedure. Spot
// data only, no session content, so public.
const layerSnapshot = table({ name: 'layer_snapshot', public: true }, {
  id: t.u64().primaryKey().autoInc(),
  spotId: t.string().index('btree'),
  layer: t.string(),        // weather | alerts
  fetchedAt: t.timestamp(), // last successful fetch (or the first failed attempt when there never was one)
  summary: t.string(),      // JSON
  geojsonUrl: t.string(),   // relative; the crew serves the polygons
  error: t.string(),        // '' when the last fetch worked
});
const layerTimer = table({ name: 'layer_timer' }, {
  scheduledId: t.u64().primaryKey().autoInc(),
  scheduledAt: t.scheduleAt(),
});
// Which map layers a session shows, shared by everyone in the set. Session data under row-level security.
const layerToggle = table({ name: 'layer_toggle', public: true }, {
  id: t.u64().primaryKey().autoInc(),
  sessionId: t.u64().index('btree'),
  layer: t.string(),
  on: t.bool(),
  updatedBy: t.identity(),
  updatedAt: t.timestamp(),
});

const voiceCall = table({ name: 'voice_call' }, {
  conversationId: t.string().primaryKey(),
  sessionId: t.u64(),   // 0 when the call named no session
  turns: t.u32(),
  durationS: t.f64(),
  summary: t.string(),
  at: t.timestamp(),
});

const spacetimedb = schema({
  rateLimit,
  config, spot, session, participant, photo, solveJob, solveResult, camera, person,
  devicePose, previewJob, message, agentStep, toast, sweepTimer, reminder, outbox, shotSettings, sceneObject,
  sessionMember, presence, presenceTimer, setEvent, activity, sceneChange, lastChange, sunClock, titleJob,
  libraryLink, publishPropOutbox, publishShotOutbox, libraryProp, publicShot, voiceCall, channelLink, shotVersion, checkin, layerSnapshot, layerTimer, layerToggle,
}, {
  // Secrets live in the database environment, set at publish time from ~/.config/shotmatch (module/scripts/publish.sh).
  // Never in source, never sent to clients.
  env: {
    NVIDIA_API_KEY: t.string().optional(),
    ELEVENLABS_WEBHOOK_SECRET: t.string().optional(),
    PUBLIC_URL: t.string().optional(),
  },
});
export default spacetimedb;

type Ctx = ReducerCtx<InferSchema<typeof spacetimedb>>;

const LEASE_US = 60_000_000n;
const MAX_ATTEMPTS = 3;
const ARRIVED_M = 8;

const cfg = (ctx: Ctx) => {
  const c = ctx.db.config.id.find(0);
  if (!c) throw new SenderError('module not initialised');
  return c;
};
const isCrew = (ctx: Ctx) => {
  const c = cfg(ctx);
  return c.crew !== undefined && c.crew.equals(ctx.sender);
};
const requireCrew = (ctx: Ctx) => { if (!isCrew(ctx)) throw new SenderError('crew only'); };
const isOwner = (ctx: Ctx) => cfg(ctx).owner.equals(ctx.sender);
const member = (ctx: Ctx, sessionId: bigint) =>
  [...ctx.db.participant.by_session_identity.filter([sessionId, ctx.sender])][0];
const requireMember = (ctx: Ctx, sessionId: bigint) => {
  if (!ctx.db.session.id.find(sessionId)) throw new SenderError('no such session');
  if (!member(ctx, sessionId) && !isCrew(ctx)) throw new SenderError('join the session first');
};
const later = (ctx: Ctx, us: bigint) => new Timestamp(ctx.timestamp.microsSinceUnixEpoch + us);
const meters = (aLat: number, aLon: number, bLat: number, bLon: number) => {
  const r = Math.PI / 180, x = (bLon - aLon) * r * Math.cos(((aLat + bLat) / 2) * r), y = (bLat - aLat) * r;
  return Math.hypot(x, y) * 6_371_000;
};
const text = (s: string, max: number) => {
  if (s.length > max) throw new SenderError(`text longer than ${max}`);
  return s;
};
const finite = (...xs: number[]) => { if (!xs.every(Number.isFinite)) throw new SenderError('non-finite number'); };

const whoName = (ctx: Ctx, sessionId: bigint) =>
  member(ctx, sessionId)?.name ?? (isCrew(ctx) ? 'Tessera crew' : isOwner(ctx) ? 'owner' : 'someone');
/** Everyone who may read the session (participants and the crew), once each: the recipients of its events. */
const audience = (ctx: Ctx, sessionId: bigint) => {
  const out = new Map<string, Identity>();
  for (const m of ctx.db.sessionMember.sessionId.filter(sessionId)) out.set(m.identity.toHexString(), m.identity);
  return [...out.values()];
};
/** A toast every member of the session sees once. */
const notify = (ctx: Ctx, sessionId: bigint, kind: string, text: string) => {
  for (const recipient of audience(ctx, sessionId)) ctx.db.toast.insert({ sessionId, kind, text, recipient });
};
/** One activity event per member: the Live data inspector's feed of who called which reducer. Never stored. */
const traceAs = (ctx: Ctx, sessionId: bigint, reducer: string, who: string, detail = '') => {
  for (const recipient of audience(ctx, sessionId))
    ctx.db.activity.insert({ recipient, sessionId, reducer, who, detail: detail.slice(0, 200) });
};
const trace = (ctx: Ctx, sessionId: bigint, reducer: string, detail = '') => traceAs(ctx, sessionId, reducer, whoName(ctx, sessionId), detail);

const COLORS = ['#E4572E', '#3A86FF', '#F3A712', '#2EC4B6', '#9B5DE5', '#F15BB5', '#8AC926', '#FF924C'];
const colorFor = (participantId: bigint) => COLORS[Number(participantId % BigInt(COLORS.length))];

const DEFAULT_PUBLIC_URL = 'https://104-238-146-229.sslip.io';
const absUrl = (ctx: Ctx, u: string) =>
  /^https?:\/\//.test(u) ? u : `${(ctx.env.PUBLIC_URL ?? DEFAULT_PUBLIC_URL).replace(/\/$/, '')}${u.startsWith('/') ? '' : '/'}${u}`;

// Default titles the title_session procedure may replace. Photon thread sessions ("photon:...") are never retitled:
// the crew finds them by that title.
const UNTITLED = new Set(['', 'Untitled shoot', 'New shoot']); // planner default, drop page default

const CODE_CHARS = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const newCode = (ctx: Ctx) => {
  for (;;) {
    let c = '';
    for (let i = 0; i < 6; i++) c += CODE_CHARS[ctx.random.integerInRange(0, CODE_CHARS.length - 1)];
    if (!ctx.db.session.code.find(c)) return c;
  }
};

const addParticipant = (ctx: Ctx, sessionId: bigint, name: string, role: string) => {
  grant(ctx, sessionId, ctx.sender, 'member');
  const existing = member(ctx, sessionId);
  if (existing) {
    ctx.db.participant.id.update({ ...existing, name, role, online: true, lastSeen: ctx.timestamp });
    return existing.id;
  }
  return ctx.db.participant.insert({ id: 0n, sessionId, identity: ctx.sender, name, role, online: true, lastSeen: ctx.timestamp }).id;
};

const grant = (ctx: Ctx, sessionId: bigint, identity: Identity, role: string) => {
  if (![...ctx.db.sessionMember.sessionId.filter(sessionId)].some(m => m.identity.equals(identity) && m.role === role))
    ctx.db.sessionMember.insert({ id: 0n, sessionId, identity, role });
};
/** Gives the current crew identity read access to one session (or every session when sessionId is omitted). */
const grantCrew = (ctx: Ctx, sessionId?: bigint) => {
  const crew = ctx.db.config.id.find(0)?.crew;
  if (!crew) return;
  for (const id of sessionId !== undefined ? [sessionId] : [...ctx.db.session.iter()].map(s => s.id)) grant(ctx, id, crew, 'crew');
};

/** Idempotent setup that init runs on a fresh database and the owner runs after a publish (init never re-runs). */
const ensureSetup = (ctx: Ctx) => {
  rateLimit.install(ctx.as.rateLimit); // idempotent: first admin is the publisher, plus its 30 s bucket sweep
  if (ctx.db.presenceTimer.count() === 0n) ctx.db.presenceTimer.insert({ scheduledId: 0n, scheduledAt: ScheduleAt.interval(10_000_000n) });
  if (ctx.db.layerTimer.count() === 0n) {
    ctx.db.layerTimer.insert({ scheduledId: 0n, scheduledAt: ScheduleAt.interval(15n * 60_000_000n) });
    ctx.db.layerTimer.insert({ scheduledId: 0n, scheduledAt: ScheduleAt.time(ctx.timestamp.microsSinceUnixEpoch) }); // one refresh now
  }
  const crew = ctx.db.config.id.find(0)?.crew;
  for (const m of [...ctx.db.sessionMember.iter()]) if (m.role === 'crew' && !(crew && m.identity.equals(crew))) ctx.db.sessionMember.id.delete(m.id);
  grantCrew(ctx);
  for (const p of [...ctx.db.participant.iter()]) grant(ctx, p.sessionId, p.identity, 'member');
};

export const init = spacetimedb.init(ctx => {
  ctx.db.config.insert({ id: 0, owner: ctx.sender, crew: undefined, crewCode: '' });
  ctx.db.sweepTimer.insert({ scheduledId: 0n, scheduledAt: ScheduleAt.interval(10_000_000n) });
  ensureSetup(ctx);
});

// `spacetime call shotmatch upgrade` after a publish: starts new schedules and backfills session_member.
export const upgrade = spacetimedb.reducer(ctx => {
  if (!isOwner(ctx)) throw new SenderError('owner only');
  ensureSetup(ctx);
  // Remove exact duplicate shot cameras left by the old client race (same name and position as the first one).
  for (const s of [...ctx.db.session.iter()]) {
    const [first, ...rest] = shotCams(ctx, s.id).sort((a, b) => Number(a.id - b.id));
    for (const c of rest) if (c.name === first.name && c.x === first.x && c.y === first.y && c.z === first.z) ctx.db.sceneObject.id.delete(c.id);
  }
  // Backfill: placed shoots still on a default title get a Nemotron title (drop-page shoots made before 'New shoot' counted).
  for (const s of [...ctx.db.session.iter()])
    if (UNTITLED.has(s.title) && [...ctx.db.solveResult.sessionId.filter(s.id)].some(r => r.confidence !== 'none'))
      ctx.db.titleJob.insert({ scheduledId: 0n, scheduledAt: ScheduleAt.time(ctx.timestamp.microsSinceUnixEpoch), sessionId: s.id });
});

export const onConnect = spacetimedb.clientConnected(ctx => {
  for (const p of ctx.db.participant.identity.filter(ctx.sender))
    ctx.db.participant.id.update({ ...p, online: true, lastSeen: ctx.timestamp });
});

export const onDisconnect = spacetimedb.clientDisconnected(ctx => {
  for (const p of ctx.db.participant.identity.filter(ctx.sender)) {
    ctx.db.participant.id.update({ ...p, online: false, lastSeen: ctx.timestamp });
    ctx.db.presence.participantId.delete(p.id);
    for (const o of [...ctx.db.sceneObject.sessionId.filter(p.sessionId)])
      if (o.lockedBy?.equals(ctx.sender)) ctx.db.sceneObject.id.update({ ...o, lockedBy: undefined });
  }
});

// The owner sets a one-time code out of band; the crew process redeems it to become the worker identity.
export const setCrewCode = spacetimedb.reducer({ code: t.string() }, (ctx, { code }) => {
  if (!isOwner(ctx)) throw new SenderError('owner only');
  if (code.length < 16) throw new SenderError('code too short');
  ctx.db.config.id.update({ ...cfg(ctx), crewCode: code });
});

export const registerCrew = spacetimedb.reducer({ code: t.string() }, (ctx, { code }) => {
  const c = cfg(ctx);
  if (!c.crewCode || code !== c.crewCode) throw new SenderError('bad crew code');
  ctx.db.config.id.update({ ...c, crew: ctx.sender });
  ensureSetup(ctx);
});

// The crew joins any session as a participant, so its edits carry a name and it shows in presence (nvidia's text-to-set).
export const joinSessionAsCrew = spacetimedb.reducer({ sessionId: t.u64(), name: t.string() }, (ctx, { sessionId, name }) => {
  requireCrew(ctx);
  if (!ctx.db.session.id.find(sessionId)) throw new SenderError('no such session');
  addParticipant(ctx, sessionId, text(name || 'Tessera', 40), 'crew');
  trace(ctx, sessionId, 'joinSessionAsCrew');
});

// The owner points this database at shotmatch-library (its database identity) for the inter-database outboxes.
export const setLibrary = spacetimedb.reducer({ db: library.identity() }, (ctx, { db }) => {
  if (!isOwner(ctx)) throw new SenderError('owner only');
  if (ctx.db.libraryLink.id.find(0)) ctx.db.libraryLink.id.update({ id: 0, db }); else ctx.db.libraryLink.insert({ id: 0, db });
});

export const upsertSpot = spacetimedb.reducer(
  { id: t.string(), name: t.string(), lat: t.f64(), lon: t.f64(), radiusM: t.f64(), cameras: t.u32(), modelVersion: t.string() },
  (ctx, s) => {
    if (!isCrew(ctx) && !isOwner(ctx)) throw new SenderError('crew only');
    finite(s.lat, s.lon, s.radiusM);
    if (ctx.db.spot.id.find(s.id)) ctx.db.spot.id.update(s); else ctx.db.spot.insert(s);
  }
);

export const createSession = spacetimedb.reducer(
  { spotId: t.string(), title: t.string(), name: t.string() },
  (ctx, { spotId, title, name }) => {
    const s = ctx.db.session.insert({
      id: 0n, code: newCode(ctx), spotId: text(spotId, 64), title: text(title, 120), owner: ctx.sender,
      planTime: undefined, createdAt: ctx.timestamp,
    });
    addParticipant(ctx, s.id, text(name, 40), isCrew(ctx) ? 'crew' : 'planner');
    grantCrew(ctx, s.id);
    trace(ctx, s.id, 'createSession', s.code);
  }
);

export const joinSession = spacetimedb.reducer(
  { code: t.string(), name: t.string(), role: t.string() },
  (ctx, { code, name, role }) => {
    const s = ctx.db.session.code.find(code.trim().toUpperCase());
    if (!s) throw new SenderError('no session with that code');
    if (role !== 'planner' && role !== 'scout') throw new SenderError('role must be planner or scout');
    addParticipant(ctx, s.id, text(name, 40), role);
    trace(ctx, s.id, 'joinSession', role);
  }
);

export const setSessionSpot = spacetimedb.reducer({ sessionId: t.u64(), spotId: t.string() }, (ctx, { sessionId, spotId }) => {
  requireMember(ctx, sessionId);
  const s = ctx.db.session.id.find(sessionId)!;
  ctx.db.session.id.update({ ...s, spotId: text(spotId, 64) });
});

export const addPhoto = spacetimedb.reducer(
  {
    sessionId: t.u64(), spotId: t.string(), url: t.string(), thumb: t.string(), width: t.u32(), height: t.u32(),
    pinLat: t.option(t.f64()), pinLon: t.option(t.f64()), exifF35: t.option(t.f64()), source: t.string(),
  },
  (ctx, a) => {
    requireMember(ctx, a.sessionId);
    text(a.url, 500); text(a.thumb, 200_000);
    const p = ctx.db.photo.insert({
      id: 0n, sessionId: a.sessionId, owner: ctx.sender, url: a.url, thumb: a.thumb, width: a.width, height: a.height,
      pinLat: a.pinLat, pinLon: a.pinLon, exifF35: a.exifF35, source: text(a.source, 16), createdAt: ctx.timestamp,
    });
    if (a.spotId) enqueue(ctx, p.id, a.sessionId, a.spotId);
    trace(ctx, a.sessionId, 'addPhoto', `photo ${p.id} from ${a.source}`);
  }
);

const enqueue = (ctx: Ctx, photoId: bigint, sessionId: bigint, spotId: string, lensHintF35?: number) =>
  ctx.db.solveJob.insert({
    id: 0n, photoId, sessionId, spotId: text(spotId, 64), state: 'queued', progress: 'waiting for a worker',
    worker: undefined, leaseUntil: undefined, attempts: 0, error: '', lensHintF35, createdAt: ctx.timestamp,
  });

export const enqueueSolve = spacetimedb.reducer(
  { photoId: t.u64(), spotId: t.string(), lensHintF35: t.option(t.f64()) },
  (ctx, { photoId, spotId, lensHintF35 }) => {
    const p = ctx.db.photo.id.find(photoId);
    if (!p) throw new SenderError('no such photo');
    requireMember(ctx, p.sessionId);
    if (lensHintF35 !== undefined && !(lensHintF35 >= 8 && lensHintF35 <= 1200)) throw new SenderError('lens hint out of range');
    enqueue(ctx, photoId, p.sessionId, spotId, lensHintF35);
    trace(ctx, p.sessionId, 'enqueueSolve', `photo ${photoId}${lensHintF35 ? `, lens hint ${lensHintF35} mm` : ''}`);
  }
);

// Refused uploads keep no location (BUILD.md, Safety), and owners can withdraw a photo.
export const deletePhoto = spacetimedb.reducer({ photoId: t.u64() }, (ctx, { photoId }) => {
  const p = ctx.db.photo.id.find(photoId);
  if (!p) return;
  if (!p.owner.equals(ctx.sender) && !isCrew(ctx)) throw new SenderError('not your photo');
  for (const j of [...ctx.db.solveJob.photoId.filter(photoId)]) ctx.db.solveJob.id.delete(j.id);
  for (const j of [...ctx.db.previewJob.sessionId.filter(p.sessionId)]) if (j.photoId === photoId) ctx.db.previewJob.id.delete(j.id);
  ctx.db.solveResult.photoId.delete(photoId);
  ctx.db.photo.id.delete(photoId);
});

export const claimJob = spacetimedb.reducer({ jobId: t.u64() }, (ctx, { jobId }) => {
  requireCrew(ctx);
  const j = ctx.db.solveJob.id.find(jobId);
  if (!j || j.state !== 'queued') throw new SenderError('job not claimable');
  ctx.db.solveJob.id.update({ ...j, state: 'running', worker: ctx.sender, leaseUntil: later(ctx, LEASE_US), attempts: j.attempts + 1, progress: 'claimed' });
  trace(ctx, j.sessionId, 'claimJob', `solve ${jobId}, attempt ${j.attempts + 1}`);
});

export const reportProgress = spacetimedb.reducer({ jobId: t.u64(), progress: t.string() }, (ctx, { jobId, progress }) => {
  requireCrew(ctx);
  const j = ctx.db.solveJob.id.find(jobId);
  if (!j || j.state !== 'running' || !j.worker?.equals(ctx.sender)) throw new SenderError('not your job');
  ctx.db.solveJob.id.update({ ...j, progress: text(progress, 200), leaseUntil: later(ctx, LEASE_US) });
  trace(ctx, j.sessionId, 'reportProgress', progress);
});

export const finishJob = spacetimedb.reducer(
  {
    jobId: t.u64(), ok: t.bool(), error: t.string(), pose: Pose, inliers: t.u32(), confidence: t.string(),
    reason: t.string(), lensReadF35: t.option(t.f64()), secs: t.f64(),
  },
  (ctx, a) => {
    requireCrew(ctx);
    const j = ctx.db.solveJob.id.find(a.jobId);
    if (!j || j.state !== 'running' || !j.worker?.equals(ctx.sender)) throw new SenderError('not your job');
    ctx.db.solveJob.id.update({ ...j, state: a.ok ? 'done' : 'failed', error: text(a.error, 500), progress: a.ok ? 'done' : 'failed', leaseUntil: undefined });
    trace(ctx, j.sessionId, 'finishJob', a.ok ? `${a.confidence}, ${a.inliers} matches` : `failed: ${a.error}`);
    if (!a.ok) {
      notify(ctx, j.sessionId, 'solve_failed', a.error);
      return;
    }
    if (!['solid', 'check', 'none'].includes(a.confidence)) throw new SenderError('bad confidence');
    const row = {
      photoId: j.photoId, sessionId: j.sessionId, jobId: j.id, pose: a.pose, inliers: a.inliers, confidence: a.confidence,
      reason: text(a.reason, 300), lensReadF35: a.lensReadF35, secs: a.secs, createdAt: ctx.timestamp,
    };
    if (ctx.db.solveResult.photoId.find(j.photoId)) ctx.db.solveResult.photoId.update(row); else ctx.db.solveResult.insert(row);
    if (a.confidence !== 'none' && !ctx.db.camera.sessionId.find(j.sessionId))
      ctx.db.camera.insert({ sessionId: j.sessionId, pose: a.pose, updatedBy: ctx.sender });
    notify(ctx, j.sessionId, 'solve_done', a.confidence === 'none' ? "Couldn't place this photo" : 'Shot located');
    // A placed photo is the moment there is enough to name the shoot: the title_session procedure asks Nemotron.
    const s = ctx.db.session.id.find(j.sessionId);
    if (a.confidence !== 'none' && s && UNTITLED.has(s.title))
      ctx.db.titleJob.insert({ scheduledId: 0n, scheduledAt: ScheduleAt.time(ctx.timestamp.microsSinceUnixEpoch), sessionId: s.id });
  }
);

export const moveCamera = spacetimedb.reducer({ sessionId: t.u64(), pose: Pose }, (ctx, { sessionId, pose }) => {
  requireMember(ctx, sessionId);
  finite(pose.lat, pose.lon, pose.alt, pose.heading, pose.pitch, pose.roll, pose.f35);
  const row = { sessionId, pose, updatedBy: ctx.sender };
  if (ctx.db.camera.sessionId.find(sessionId)) ctx.db.camera.sessionId.update(row); else ctx.db.camera.insert(row);
  trace(ctx, sessionId, 'moveCamera', `heading ${pose.heading.toFixed(0)}, ${pose.f35.toFixed(0)} mm`);
});

export const placePerson = spacetimedb.reducer(
  { sessionId: t.u64(), id: t.u64(), lat: t.f64(), lon: t.f64(), heading: t.f64(), label: t.string() },
  (ctx, a) => {
    requireMember(ctx, a.sessionId);
    finite(a.lat, a.lon, a.heading);
    const row = { id: a.id, sessionId: a.sessionId, lat: a.lat, lon: a.lon, heading: a.heading, label: text(a.label, 40) };
    const old = a.id ? ctx.db.person.id.find(a.id) : undefined;
    if (old) {
      if (old.sessionId !== a.sessionId) throw new SenderError('person is in another session');
      ctx.db.person.id.update({ ...old, ...row });
    } else ctx.db.person.insert({ ...row, id: 0n, pose: 'stand', heightM: 1.7 });
    trace(ctx, a.sessionId, 'placePerson', a.label);
  }
);

export const setPersonPose = spacetimedb.reducer({ id: t.u64(), pose: t.string(), heightM: t.f64() }, (ctx, a) => {
  const p = ctx.db.person.id.find(a.id);
  if (!p) throw new SenderError('no such person');
  requireMember(ctx, p.sessionId);
  if (!['stand', 'walk', 'sit', 'lean', 'point', 'jump'].includes(a.pose)) throw new SenderError('unknown pose');
  if (!(a.heightM >= 0.5 && a.heightM <= 2.3)) throw new SenderError('height out of range');
  ctx.db.person.id.update({ ...p, pose: a.pose, heightM: a.heightM });
  trace(ctx, p.sessionId, 'setPersonPose', `${p.label}: ${a.pose}`);
});

export const setShotSettings = spacetimedb.reducer(
  {
    sessionId: t.u64(), bodyId: t.string(), lensId: t.string(), focalMm: t.f64(), aperture: t.f64(), shutterS: t.f64(),
    iso: t.u32(), whiteBalanceK: t.u32(), focusM: t.f64(), aspect: t.string(), overlays: t.string(), distortion: t.bool(),
  },
  (ctx, a) => {
    requireMember(ctx, a.sessionId);
    finite(a.focalMm, a.aperture, a.shutterS, a.focusM);
    if (!(a.focalMm > 1 && a.focalMm < 2000 && a.aperture >= 0.7 && a.aperture <= 64 && a.shutterS > 0 && a.shutterS <= 3600 && a.focusM > 0))
      throw new SenderError('camera setting out of range');
    if (a.iso < 25 || a.iso > 409600 || a.whiteBalanceK < 1500 || a.whiteBalanceK > 15000) throw new SenderError('camera setting out of range');
    const row = { ...a, bodyId: text(a.bodyId, 64), lensId: text(a.lensId, 96), aspect: text(a.aspect, 8), overlays: text(a.overlays, 80), updatedBy: ctx.sender };
    if (ctx.db.shotSettings.sessionId.find(a.sessionId)) ctx.db.shotSettings.sessionId.update(row); else ctx.db.shotSettings.insert(row);
    trace(ctx, a.sessionId, 'setShotSettings', `${a.focalMm} mm f/${a.aperture} ISO ${a.iso}`);
  }
);

const SCENE_KINDS = ['model', 'person', 'light', 'camera', 'prop_generated', 'text'];
const OBJ = {
  sessionId: t.u64(), kind: t.string(), assetId: t.string(), name: t.string(),
  x: t.f64(), y: t.f64(), z: t.f64(), qx: t.f64(), qy: t.f64(), qz: t.f64(), qw: t.f64(), scale: t.f64(),
  color: t.string(), intensity: t.f64(), lightType: t.string(), params: t.string(), visible: t.bool(),
};
type ObjArgs = { sessionId: bigint; kind: string; assetId: string; name: string; x: number; y: number; z: number;
  qx: number; qy: number; qz: number; qw: number; scale: number; color: string; intensity: number; lightType: string; params: string; visible: boolean };
const checkObj = (a: ObjArgs) => {
  if (!SCENE_KINDS.includes(a.kind)) throw new SenderError('unknown object kind');
  finite(a.x, a.y, a.z, a.qx, a.qy, a.qz, a.qw, a.scale, a.intensity);
  if (Math.abs(a.x) > 5000 || Math.abs(a.y) > 5000 || Math.abs(a.z) > 2000) throw new SenderError('object too far from the spot');
  if (!(a.scale > 0 && a.scale <= 1000)) throw new SenderError('bad scale');
  const n = Math.hypot(a.qx, a.qy, a.qz, a.qw);
  if (!(n > 0.5 && n < 1.5)) throw new SenderError('rotation must be a unit quaternion');
  return { ...a, assetId: text(a.assetId, 300), name: text(a.name, 80), color: text(a.color, 16), lightType: text(a.lightType, 16), params: text(a.params, 500) };
};
const MAX_OBJECTS = 300;

// The editable fields of an object as JSON: what scene_change stores before and after each edit.
const SNAP_KEYS = ['kind', 'assetId', 'name', 'x', 'y', 'z', 'qx', 'qy', 'qz', 'qw', 'scale', 'color', 'intensity', 'lightType', 'params', 'visible'] as const;
const snap = (o: Omit<ObjArgs, 'sessionId'>) => JSON.stringify(Object.fromEntries(SNAP_KEYS.map(k => [k, o[k]])));
const FOLD_US = 2_000_000n; // edits by one person to one object less than 2 s apart are one history entry (a drag)

const recordChange = (ctx: Ctx, sessionId: bigint, objectId: bigint, action: string, before: string, after: string) => {
  if (before === after) return;
  const lc = ctx.db.lastChange.objectId.find(objectId);
  const prev = lc && ctx.db.sceneChange.id.find(lc.changeId);
  if (action === 'update' && prev && prev.action === 'update' && prev.by.equals(ctx.sender)
      && ctx.timestamp.microsSinceUnixEpoch - prev.at.microsSinceUnixEpoch < FOLD_US) {
    ctx.db.sceneChange.id.update({ ...prev, after, at: ctx.timestamp });
    return;
  }
  const c = ctx.db.sceneChange.insert({ id: 0n, sessionId, objectId, action, before, after, by: ctx.sender, byName: whoName(ctx, sessionId), at: ctx.timestamp });
  if (lc) ctx.db.lastChange.objectId.update({ objectId, changeId: c.id }); else ctx.db.lastChange.insert({ objectId, changeId: c.id });
};

/** Puts one object into a stored state ('' = absent), recorded as `action` so undo and restore are themselves undoable. */
const applyState = (ctx: Ctx, sessionId: bigint, objectId: bigint, state: string, action: string) => {
  const cur = ctx.db.sceneObject.id.find(objectId);
  if (cur && cur.sessionId !== sessionId) throw new SenderError('object is in another session');
  if (cur?.lockedBy && !cur.lockedBy.equals(ctx.sender)) throw new SenderError(`${cur.name || 'an object'} is being moved by someone else`);
  const before = cur ? snap(cur) : '';
  if (!state) { if (cur) ctx.db.sceneObject.id.delete(objectId); }
  else {
    const fields = checkObj({ ...JSON.parse(state), sessionId });
    if (cur) ctx.db.sceneObject.id.update({ ...cur, ...fields, updatedBy: ctx.sender, updatedAt: ctx.timestamp });
    else ctx.db.sceneObject.insert({ ...fields, id: objectId, lockedBy: undefined, updatedBy: ctx.sender, updatedAt: ctx.timestamp });
  }
  recordChange(ctx, sessionId, objectId, action, before, state);
};

/** A TRELLIS prop added in one session goes to shotmatch-library, so every session can reuse it. */
const sharePropToLibrary = (ctx: Ctx, sessionId: bigint, o: { kind: string; assetId: string; name: string; params: string }) => {
  if (o.kind !== 'prop_generated' || !o.assetId) return;
  const link = ctx.db.libraryLink.id.find(0);
  const assetUrl = absUrl(ctx, o.assetId);
  if (!link || ctx.db.libraryProp.assetUrl.find(assetUrl)) return;
  const prompt = /(?:^|;)prompt=([^;]*)/.exec(o.params)?.[1] ?? o.name;
  ctx.db.publishPropOutbox.insert({ msgId: 0n, target: link.db, assetUrl, name: o.name.slice(0, 80), prompt: prompt.slice(0, 500), sessionId });
};

// The shot camera ("Cam A") is the camera whose params say shot=1. One per session.
const isShotCam = (o: { kind: string; params: string }) => o.kind === 'camera' && /(?:^|;)shot=1(?:;|$)/.test(o.params);
const shotCams = (ctx: Ctx, sessionId: bigint) => [...ctx.db.sceneObject.sessionId.filter(sessionId)].filter(isShotCam);

export const addSceneObject = spacetimedb.reducer(OBJ, (ctx, a) => {
  requireMember(ctx, a.sessionId);
  // Every open tab races to create Cam A when it is missing; transactions run one at a time, so the first one wins.
  if (isShotCam(a) && shotCams(ctx, a.sessionId).length) return;
  if ([...ctx.db.sceneObject.sessionId.filter(a.sessionId)].length >= MAX_OBJECTS) throw new SenderError('scene is full');
  const o = ctx.db.sceneObject.insert({ ...checkObj(a), id: 0n, lockedBy: undefined, updatedBy: ctx.sender, updatedAt: ctx.timestamp });
  recordChange(ctx, a.sessionId, o.id, 'add', '', snap(o));
  sharePropToLibrary(ctx, a.sessionId, o);
  trace(ctx, a.sessionId, 'addSceneObject', `${o.kind} ${o.name || o.assetId} #${o.id}`);
});

export const updateSceneObject = spacetimedb.reducer({ id: t.u64(), ...OBJ }, (ctx, { id, ...a }) => {
  const o = ctx.db.sceneObject.id.find(id);
  if (!o || o.sessionId !== a.sessionId) throw new SenderError('no such object in this session');
  requireMember(ctx, a.sessionId);
  if (o.lockedBy && !o.lockedBy.equals(ctx.sender)) throw new SenderError('someone else is moving this object');
  const next = { ...o, ...checkObj(a), updatedBy: ctx.sender, updatedAt: ctx.timestamp };
  ctx.db.sceneObject.id.update(next);
  recordChange(ctx, a.sessionId, id, 'update', snap(o), snap(next));
  trace(ctx, a.sessionId, 'updateSceneObject', `#${id} ${o.name} (${a.x.toFixed(2)}, ${a.y.toFixed(2)}, ${a.z.toFixed(2)})`);
});

export const lockSceneObject = spacetimedb.reducer({ id: t.u64(), lock: t.bool() }, (ctx, { id, lock }) => {
  const o = ctx.db.sceneObject.id.find(id);
  if (!o) throw new SenderError('no such object');
  requireMember(ctx, o.sessionId);
  // Grabbing and releasing are both the holder's (or the crew's); the presence sweep frees locks of silent editors.
  if (o.lockedBy && !o.lockedBy.equals(ctx.sender) && (lock || !isCrew(ctx))) throw new SenderError('someone else is moving this object');
  ctx.db.sceneObject.id.update({ ...o, lockedBy: lock ? ctx.sender : undefined });
  trace(ctx, o.sessionId, 'lockSceneObject', `#${id} ${lock ? 'grabbed' : 'released'}`);
});

export const deleteSceneObject = spacetimedb.reducer({ id: t.u64() }, (ctx, { id }) => {
  const o = ctx.db.sceneObject.id.find(id);
  if (!o) return;
  requireMember(ctx, o.sessionId);
  if (o.lockedBy && !o.lockedBy.equals(ctx.sender)) throw new SenderError('someone else is moving this object');
  ctx.db.sceneObject.id.delete(id);
  recordChange(ctx, o.sessionId, id, 'delete', snap(o), '');
  trace(ctx, o.sessionId, 'deleteSceneObject', `#${id} ${o.name}`);
});

// Anyone in the session can undo anyone's change: the object goes back to the state before that change.
export const undoSceneChange = spacetimedb.reducer({ changeId: t.u64() }, (ctx, { changeId }) => {
  const c = ctx.db.sceneChange.id.find(changeId);
  if (!c) throw new SenderError('no such change');
  requireMember(ctx, c.sessionId);
  applyState(ctx, c.sessionId, c.objectId, c.before, 'undo');
  trace(ctx, c.sessionId, 'undoSceneChange', `${c.action} by ${c.byName} on #${c.objectId}`);
});

// Time travel: put the whole set back the way it was right after change `changeId` (0 = before the first change).
// Each object touched since goes to the `before` state of its earliest later change, as one transaction.
const restoreTo = (ctx: Ctx, sessionId: bigint, changeId: bigint) => {
  const target = new Map<bigint, { id: bigint; before: string }>();
  for (const c of ctx.db.sceneChange.sessionId.filter(sessionId)) {
    if (c.id <= changeId) continue;
    const t0 = target.get(c.objectId);
    if (!t0 || c.id < t0.id) target.set(c.objectId, { id: c.id, before: c.before });
  }
  let n = 0;
  for (const [objectId, s] of target) {
    // Restoring brings back people and props; it never deletes the shot camera or adds a second one.
    const cur = ctx.db.sceneObject.id.find(objectId);
    if (cur && isShotCam(cur) && !s.before) continue;
    if (!cur && s.before && isShotCam(JSON.parse(s.before)) && shotCams(ctx, sessionId).length) continue;
    applyState(ctx, sessionId, objectId, s.before, 'restore');
    n++;
  }
  return n;
};
const latestChange = (ctx: Ctx, sessionId: bigint) =>
  [...ctx.db.sceneChange.sessionId.filter(sessionId)].reduce((m, c) => (c.id > m ? c.id : m), 0n);

export const restoreSceneTo = spacetimedb.reducer({ sessionId: t.u64(), changeId: t.u64() }, (ctx, { sessionId, changeId }) => {
  requireMember(ctx, sessionId);
  const n = restoreTo(ctx, sessionId, changeId);
  trace(ctx, sessionId, 'restoreSceneTo', `change ${changeId}, ${n} objects`);
});

// ---------------------------------------------------------------------------------------------------------------
// Photon: channel links, shot versions (a text thread as a version tree over scene history) and scout check-ins.

const CHANNELS = ['imessage', 'telegram', 'sms', 'whatsapp', 'email', 'voice'];

// A member links their own channel. The crew may link any participant of the session (participantId), or an invitee
// who has not opened the web app yet (participantId 0: stored with participantId 0 and Identity.zero()). When the
// invitee joins, the crew calls again with the real participantId and the same (channel, address) row is updated.
export const addChannelLink = spacetimedb.reducer(
  { sessionId: t.u64(), channel: t.string(), address: t.string(), participantId: t.option(t.u64()), name: t.option(t.string()) },
  (ctx, a) => {
    requireMember(ctx, a.sessionId);
    if (!CHANNELS.includes(a.channel)) throw new SenderError('unknown channel');
    const address = text(a.address.trim(), 200);
    if (!address) throw new SenderError('address required');
    const crew = isCrew(ctx);
    const invited = crew && a.participantId === 0n;
    const p = invited ? undefined : a.participantId !== undefined && crew ? ctx.db.participant.id.find(a.participantId) : member(ctx, a.sessionId);
    if (!invited && (!p || p.sessionId !== a.sessionId)) throw new SenderError('no such participant in this session');
    const name = a.name !== undefined ? text(a.name.trim(), 40) : undefined;
    const old = [...ctx.db.channelLink.sessionId.filter(a.sessionId)].find(l => l.channel === a.channel && l.address === address);
    // An invite never unlinks someone who has already joined.
    const who = p ? { participantId: p.id, identity: p.identity } : old && old.participantId !== 0n ? {} : { participantId: 0n, identity: Identity.zero() };
    if (old) ctx.db.channelLink.id.update({ ...old, ...who, name: name ?? old.name });
    else ctx.db.channelLink.insert({
      id: 0n, sessionId: a.sessionId, participantId: p?.id ?? 0n, identity: p?.identity ?? Identity.zero(), channel: a.channel, address,
      verified: false, createdAt: ctx.timestamp, name: name ?? p?.name ?? '',
    });
    trace(ctx, a.sessionId, 'addChannelLink', `${name ?? p?.name ?? 'invitee'}: ${a.channel}${invited ? ' (invited)' : ''}`);
  }
);

// The person the link belongs to, the session's owner, or the crew.
export const removeChannelLink = spacetimedb.reducer({ id: t.u64() }, (ctx, { id }) => {
  const l = ctx.db.channelLink.id.find(id);
  if (!l) return;
  requireMember(ctx, l.sessionId);
  if (!l.identity.equals(ctx.sender) && !isCrew(ctx) && !ctx.db.session.id.find(l.sessionId)?.owner.equals(ctx.sender))
    throw new SenderError('not your link');
  ctx.db.channelLink.id.delete(id);
  trace(ctx, l.sessionId, 'removeChannelLink', l.channel);
});

export const markChannelVerified = spacetimedb.reducer({ id: t.u64(), verified: t.bool() }, (ctx, { id, verified }) => {
  requireCrew(ctx);
  const l = ctx.db.channelLink.id.find(id);
  if (!l) throw new SenderError('no such link');
  ctx.db.channelLink.id.update({ ...l, verified });
  trace(ctx, l.sessionId, 'markChannelVerified', `${l.channel} ${verified ? 'verified' : 'unverified'}`);
});

const nextVersionLabel = (ctx: Ctx, sessionId: bigint, parent?: { id: bigint; label: string }) => {
  const all = [...ctx.db.shotVersion.sessionId.filter(sessionId)];
  if (!parent) return `v${all.filter(v => /^v\d+$/.test(v.label)).length + 1}`;
  return `${parent.label}.${all.filter(v => v.parentVersionId === parent.id && v.label.startsWith(`${parent.label}.`)).length + 1}`;
};

// The crew records a version when a thread produces a new plan or render. sceneChangeId defaults to the latest change.
export const recordShotVersion = spacetimedb.reducer(
  {
    sessionId: t.u64(), parentVersionId: t.option(t.u64()), label: t.string(), externalMessageId: t.string(), channel: t.string(),
    imageUrl: t.string(), sceneChangeId: t.option(t.u64()),
  },
  (ctx, a) => {
    requireCrew(ctx);
    if (!ctx.db.session.id.find(a.sessionId)) throw new SenderError('no such session');
    const parent = a.parentVersionId !== undefined ? ctx.db.shotVersion.id.find(a.parentVersionId) ?? undefined : undefined;
    if (a.parentVersionId !== undefined && (!parent || parent.sessionId !== a.sessionId)) throw new SenderError('parent version is not in this session');
    const sceneChangeId = a.sceneChangeId ?? latestChange(ctx, a.sessionId);
    const c = sceneChangeId ? ctx.db.sceneChange.id.find(sceneChangeId) : undefined;
    if (sceneChangeId && (!c || c.sessionId !== a.sessionId)) throw new SenderError('scene change is not in this session');
    const v = ctx.db.shotVersion.insert({
      id: 0n, sessionId: a.sessionId, parentVersionId: a.parentVersionId, label: text(a.label, 24) || nextVersionLabel(ctx, a.sessionId), // thread versions count v1, v2, v3; forks get v3.1
      externalMessageId: text(a.externalMessageId, 200), channel: text(a.channel, 16), sceneChangeId, imageUrl: text(a.imageUrl, 500), createdAt: ctx.timestamp,
    });
    trace(ctx, a.sessionId, 'recordShotVersion', `${v.label} at change ${sceneChangeId}`);
  }
);

// A version's render or edit often lands after its row exists (a fork is recorded before the reply's edit and render).
// '' keeps the image and none keeps the scene change.
export const updateShotVersion = spacetimedb.reducer({ id: t.u64(), imageUrl: t.string(), sceneChangeId: t.option(t.u64()) }, (ctx, a) => {
  requireCrew(ctx);
  const v = ctx.db.shotVersion.id.find(a.id);
  if (!v) throw new SenderError('no such version');
  if (a.sceneChangeId !== undefined && a.sceneChangeId !== 0n && ctx.db.sceneChange.id.find(a.sceneChangeId)?.sessionId !== v.sessionId)
    throw new SenderError('scene change is not in this session');
  ctx.db.shotVersion.id.update({ ...v, imageUrl: a.imageUrl ? text(a.imageUrl, 500) : v.imageUrl, sceneChangeId: a.sceneChangeId ?? v.sceneChangeId });
  trace(ctx, v.sessionId, 'updateShotVersion', `${v.label}${a.imageUrl ? ' image' : ''}${a.sceneChangeId !== undefined ? ` at change ${a.sceneChangeId}` : ''}`);
});

// Fork: put the set back to a version's snapshot and record that as a new branch under it (v3 -> v3.1). The restore is
// ordinary scene history (restore rows), so the fork itself can be undone or scrubbed past.
export const restoreToVersion = spacetimedb.reducer(
  { versionId: t.u64(), channel: t.string(), externalMessageId: t.string() },
  (ctx, a) => {
    const v = ctx.db.shotVersion.id.find(a.versionId);
    if (!v) throw new SenderError('no such version');
    requireMember(ctx, v.sessionId);
    const n = restoreTo(ctx, v.sessionId, v.sceneChangeId);
    const label = nextVersionLabel(ctx, v.sessionId, v);
    ctx.db.shotVersion.insert({
      id: 0n, sessionId: v.sessionId, parentVersionId: v.id, label, externalMessageId: text(a.externalMessageId, 200),
      channel: text(a.channel || 'web', 16), sceneChangeId: latestChange(ctx, v.sessionId), imageUrl: '', createdAt: ctx.timestamp,
    });
    notify(ctx, v.sessionId, 'version_forked', `Back to ${v.label}: the set is now ${label}`);
    trace(ctx, v.sessionId, 'restoreToVersion', `${v.label} -> ${label}, ${n} objects`);
  }
);

// participantId 0 is a scout who is only on a text channel (no participant), named by `name`, as with invite links.
export const recordCheckin = spacetimedb.reducer(
  {
    sessionId: t.u64(), participantId: t.u64(), photoId: t.u64(), distanceM: t.f64(), headingErrDeg: t.f64(), verdict: t.string(),
    x: t.option(t.f64()), y: t.option(t.f64()), heading: t.option(t.f64()), imageUrl: t.option(t.string()), name: t.option(t.string()),
  },
  (ctx, a) => {
    requireCrew(ctx);
    if (!ctx.db.session.id.find(a.sessionId)) throw new SenderError('no such session');
    finite(a.distanceM, a.headingErrDeg, a.x ?? 0, a.y ?? 0, a.heading ?? 0);
    const p = a.participantId === 0n ? undefined : ctx.db.participant.id.find(a.participantId);
    if (a.participantId !== 0n && (!p || p.sessionId !== a.sessionId)) throw new SenderError('no such participant in this session');
    const name = text((a.name ?? '').trim(), 40) || p?.name || 'A scout';
    ctx.db.checkin.insert({
      id: 0n, sessionId: a.sessionId, participantId: a.participantId, photoId: a.photoId, distanceM: a.distanceM, headingErrDeg: a.headingErrDeg,
      verdict: text(a.verdict, 40), createdAt: ctx.timestamp, x: a.x ?? 0, y: a.y ?? 0, heading: a.heading ?? 0, imageUrl: text(a.imageUrl ?? '', 500), name,
    });
    notify(ctx, a.sessionId, 'checkin', `${name} checked in: ${a.verdict}, ${a.distanceM.toFixed(1)} m and ${Math.abs(a.headingErrDeg).toFixed(0)}° off the mark`);
    trace(ctx, a.sessionId, 'recordCheckin', `${name}: ${a.verdict}`);
  }
);

export const removePerson = spacetimedb.reducer({ id: t.u64() }, (ctx, { id }) => {
  const p = ctx.db.person.id.find(id);
  if (!p) return;
  requireMember(ctx, p.sessionId);
  ctx.db.person.id.delete(id);
  trace(ctx, p.sessionId, 'removePerson', p.label);
});

export const setPlanTime = spacetimedb.reducer({ sessionId: t.u64(), at: t.option(t.timestamp()) }, (ctx, { sessionId, at }) => {
  requireMember(ctx, sessionId);
  ctx.db.session.id.update({ ...ctx.db.session.id.find(sessionId)!, planTime: at });
  // Picking a time by hand turns Live sun off (sun_tick would snap it back to now); a time-lapse keeps running from here.
  const clock = ctx.db.sunClock.sessionId.find(sessionId);
  if (clock && clock.rate === 1) ctx.db.sunClock.scheduledId.delete(clock.scheduledId);
  trace(ctx, sessionId, 'setPlanTime', clock?.rate === 1 ? 'live sun off' : '');
});

export const pushDevicePose = spacetimedb.reducer(
  { sessionId: t.u64(), lat: t.f64(), lon: t.f64(), accuracyM: t.f64(), heading: t.option(t.f64()) },
  (ctx, a) => {
    const me = member(ctx, a.sessionId);
    if (!me) throw new SenderError('join the session first');
    finite(a.lat, a.lon, a.accuracyM);
    const prev = ctx.db.devicePose.participantId.find(me.id);
    const row = { participantId: me.id, sessionId: a.sessionId, lat: a.lat, lon: a.lon, accuracyM: a.accuracyM, heading: a.heading, at: ctx.timestamp };
    if (prev) ctx.db.devicePose.participantId.update(row); else ctx.db.devicePose.insert(row);
    const cam = ctx.db.camera.sessionId.find(a.sessionId);
    if (cam) {
      const d = meters(a.lat, a.lon, cam.pose.lat, cam.pose.lon);
      const before = prev ? meters(prev.lat, prev.lon, cam.pose.lat, cam.pose.lon) : Infinity;
      if (d <= ARRIVED_M && before > ARRIVED_M) notify(ctx, a.sessionId, 'scout_arrived', `${me.name} reached the spot`);
    }
  }
);

export const requestPreview = spacetimedb.reducer(
  {
    sessionId: t.u64(), photoId: t.u64(), instruction: t.string(), f35: t.option(t.f64()), people: t.u32(),
    sunAzimuth: t.option(t.f64()), sunAltitude: t.option(t.f64()),
  },
  (ctx, a) => {
    requireMember(ctx, a.sessionId);
    const p = ctx.db.photo.id.find(a.photoId);
    if (!p || p.sessionId !== a.sessionId) throw new SenderError('photo not in this session');
    ctx.db.previewJob.insert({
      id: 0n, sessionId: a.sessionId, photoId: a.photoId, instruction: text(a.instruction, 500), f35: a.f35, people: a.people,
      sunAzimuth: a.sunAzimuth, sunAltitude: a.sunAltitude, state: 'queued', imageUrl: '', error: '', worker: undefined,
      leaseUntil: undefined, attempts: 0, createdAt: ctx.timestamp, kind: 'preview', requestId: '',
    });
    trace(ctx, a.sessionId, 'requestPreview', a.instruction);
  }
);

// The studio's AI render pass: the crew receives the layers over HTTP, so it creates the row already running.
// requestId is the crew's own id for the request, so it can find the row it just made.
export const startRender = spacetimedb.reducer(
  {
    sessionId: t.u64(), photoId: t.u64(), requestId: t.string(), instruction: t.string(), f35: t.option(t.f64()), people: t.u32(),
    sunAzimuth: t.option(t.f64()), sunAltitude: t.option(t.f64()),
  },
  (ctx, a) => {
    requireCrew(ctx);
    if (!ctx.db.session.id.find(a.sessionId)) throw new SenderError('no such session');
    if (!a.requestId) throw new SenderError('requestId required');
    ctx.db.previewJob.insert({
      id: 0n, sessionId: a.sessionId, photoId: a.photoId, instruction: text(a.instruction, 500), f35: a.f35, people: a.people,
      sunAzimuth: a.sunAzimuth, sunAltitude: a.sunAltitude, state: 'running', imageUrl: '', error: '', worker: ctx.sender,
      leaseUntil: later(ctx, LEASE_US * 3n), attempts: 1, createdAt: ctx.timestamp, kind: 'render', requestId: text(a.requestId, 64),
    });
    trace(ctx, a.sessionId, 'startRender', a.instruction);
  }
);

export const claimPreview = spacetimedb.reducer({ jobId: t.u64() }, (ctx, { jobId }) => {
  requireCrew(ctx);
  const j = ctx.db.previewJob.id.find(jobId);
  if (!j || j.state !== 'queued') throw new SenderError('job not claimable');
  ctx.db.previewJob.id.update({ ...j, state: 'running', worker: ctx.sender, leaseUntil: later(ctx, LEASE_US * 3n), attempts: j.attempts + 1 });
  trace(ctx, j.sessionId, 'claimPreview', `preview ${jobId}`);
});

export const renewPreview = spacetimedb.reducer({ jobId: t.u64() }, (ctx, { jobId }) => {
  requireCrew(ctx);
  const j = ctx.db.previewJob.id.find(jobId);
  if (!j || j.state !== 'running' || !j.worker?.equals(ctx.sender)) throw new SenderError('not your job');
  ctx.db.previewJob.id.update({ ...j, leaseUntil: later(ctx, LEASE_US * 3n) });
});

export const finishPreview = spacetimedb.reducer(
  { jobId: t.u64(), ok: t.bool(), imageUrl: t.string(), error: t.string() },
  (ctx, a) => {
    requireCrew(ctx);
    const j = ctx.db.previewJob.id.find(a.jobId);
    if (!j || j.state !== 'running' || !j.worker?.equals(ctx.sender)) throw new SenderError('not your job');
    ctx.db.previewJob.id.update({ ...j, state: a.ok ? 'done' : 'failed', imageUrl: text(a.imageUrl, 500), error: text(a.error, 500), leaseUntil: undefined });
    const what = j.kind === 'render' ? 'Render' : 'Preview';
    notify(ctx, j.sessionId, a.ok ? `${j.kind}_done` : `${j.kind}_failed`, a.ok ? `${what} ready` : a.error);
    trace(ctx, j.sessionId, 'finishPreview', `${j.kind} ${a.jobId} ${a.ok ? 'done' : 'failed'}`);
  }
);

export const postMessage = spacetimedb.reducer(
  {
    sessionId: t.u64(), channel: t.string(), threadId: t.string(), externalId: t.string(), parentExternalId: t.string(),
    direction: t.string(), author: t.string(), text: t.string(), imageUrl: t.string(),
  },
  (ctx, a) => {
    requireMember(ctx, a.sessionId);
    if (a.channel !== 'web' && !isCrew(ctx)) throw new SenderError('only the crew relays outside channels');
    if (a.direction !== 'in' && a.direction !== 'out') throw new SenderError('bad direction');
    if (a.direction === 'out' && !isCrew(ctx)) throw new SenderError('crew only');
    ctx.db.message.insert({
      id: 0n, sessionId: a.sessionId, channel: text(a.channel, 16), threadId: text(a.threadId, 200), externalId: text(a.externalId, 200),
      parentExternalId: text(a.parentExternalId, 200), direction: a.direction, author: text(a.author, 80), text: text(a.text, 4000),
      imageUrl: text(a.imageUrl, 500), createdAt: ctx.timestamp,
    });
    trace(ctx, a.sessionId, 'postMessage', `${a.channel} ${a.direction}`);
  }
);

export const logAgentStep = spacetimedb.reducer(
  { sessionId: t.u64(), tool: t.string(), args: t.string(), result: t.string(), ms: t.u32() },
  (ctx, a) => {
    requireCrew(ctx);
    ctx.db.agentStep.insert({ id: 0n, sessionId: a.sessionId, tool: text(a.tool, 60), args: text(a.args, 2000), result: text(a.result, 4000), ms: a.ms, at: ctx.timestamp });
    trace(ctx, a.sessionId, 'logAgentStep', `${a.tool} ${a.ms} ms`);
  }
);

export const scheduleReminder = spacetimedb.reducer(
  { sessionId: t.u64(), atMicros: t.i64(), text: t.string() },
  (ctx, a) => {
    requireMember(ctx, a.sessionId);
    if (a.atMicros <= ctx.timestamp.microsSinceUnixEpoch) throw new SenderError('reminder time is in the past');
    for (const r of [...ctx.db.reminder.sessionId.filter(a.sessionId)]) ctx.db.reminder.scheduledId.delete(r.scheduledId);
    ctx.db.reminder.insert({ scheduledId: 0n, scheduledAt: ScheduleAt.time(a.atMicros), sessionId: a.sessionId, text: text(a.text, 300) });
    trace(ctx, a.sessionId, 'scheduleReminder', new Timestamp(a.atMicros).toDate().toISOString());
  }
);

export const cancelReminder = spacetimedb.reducer({ sessionId: t.u64() }, (ctx, { sessionId }) => {
  requireMember(ctx, sessionId);
  for (const r of [...ctx.db.reminder.sessionId.filter(sessionId)]) ctx.db.reminder.scheduledId.delete(r.scheduledId);
});

export const fireReminder = spacetimedb.reducer({ onSchedule: reminder }, { r: reminder.rowType }, (ctx, { r }) => {
  notify(ctx, r.sessionId, 'reminder', r.text);
  ctx.db.outbox.insert({ id: 0n, sessionId: r.sessionId, text: r.text, state: 'pending', createdAt: ctx.timestamp });
  traceAs(ctx, r.sessionId, 'fireReminder', 'schedule', r.text.slice(0, 200));
});

export const markOutbox = spacetimedb.reducer({ id: t.u64(), state: t.string() }, (ctx, { id, state }) => {
  requireCrew(ctx);
  const o = ctx.db.outbox.id.find(id);
  if (!o) return;
  if (state !== 'sent' && state !== 'failed') throw new SenderError('bad state');
  ctx.db.outbox.id.update({ ...o, state });
});

// Session owner or crew removes a session and everything in it.
export const deleteSession = spacetimedb.reducer({ sessionId: t.u64() }, (ctx, { sessionId }) => {
  const s = ctx.db.session.id.find(sessionId);
  if (!s) return;
  if (!s.owner.equals(ctx.sender) && !isCrew(ctx) && !isOwner(ctx)) throw new SenderError('not your session');
  for (const x of [...ctx.db.photo.sessionId.filter(sessionId)]) ctx.db.photo.id.delete(x.id);
  for (const x of [...ctx.db.solveJob.sessionId.filter(sessionId)]) ctx.db.solveJob.id.delete(x.id);
  for (const x of [...ctx.db.solveResult.sessionId.filter(sessionId)]) ctx.db.solveResult.photoId.delete(x.photoId);
  for (const x of [...ctx.db.previewJob.sessionId.filter(sessionId)]) ctx.db.previewJob.id.delete(x.id);
  for (const x of [...ctx.db.person.sessionId.filter(sessionId)]) ctx.db.person.id.delete(x.id);
  ctx.db.shotSettings.sessionId.delete(sessionId);
  for (const x of [...ctx.db.sceneObject.sessionId.filter(sessionId)]) ctx.db.sceneObject.id.delete(x.id);
  for (const x of [...ctx.db.devicePose.sessionId.filter(sessionId)]) ctx.db.devicePose.participantId.delete(x.participantId);
  for (const x of [...ctx.db.message.sessionId.filter(sessionId)]) ctx.db.message.id.delete(x.id);
  for (const x of [...ctx.db.agentStep.sessionId.filter(sessionId)]) ctx.db.agentStep.id.delete(x.id);
  for (const x of [...ctx.db.reminder.sessionId.filter(sessionId)]) ctx.db.reminder.scheduledId.delete(x.scheduledId);
  for (const x of [...ctx.db.outbox.sessionId.filter(sessionId)]) ctx.db.outbox.id.delete(x.id);
  for (const x of [...ctx.db.presence.sessionId.filter(sessionId)]) ctx.db.presence.participantId.delete(x.participantId);
  for (const x of [...ctx.db.sceneChange.sessionId.filter(sessionId)]) { ctx.db.lastChange.objectId.delete(x.objectId); ctx.db.sceneChange.id.delete(x.id); }
  const clock = ctx.db.sunClock.sessionId.find(sessionId);
  if (clock) ctx.db.sunClock.scheduledId.delete(clock.scheduledId);
  for (const x of [...ctx.db.publicShot.sessionId.filter(sessionId)]) ctx.db.publicShot.shareCode.delete(x.shareCode);
  for (const x of [...ctx.db.channelLink.sessionId.filter(sessionId)]) ctx.db.channelLink.id.delete(x.id);
  for (const x of [...ctx.db.layerToggle.sessionId.filter(sessionId)]) ctx.db.layerToggle.id.delete(x.id);
  for (const x of [...ctx.db.shotVersion.sessionId.filter(sessionId)]) ctx.db.shotVersion.id.delete(x.id);
  for (const x of [...ctx.db.checkin.sessionId.filter(sessionId)]) ctx.db.checkin.id.delete(x.id);
  for (const x of [...ctx.db.sessionMember.sessionId.filter(sessionId)]) ctx.db.sessionMember.id.delete(x.id);
  for (const x of [...ctx.db.participant.sessionId.filter(sessionId)]) ctx.db.participant.id.delete(x.id);
  ctx.db.camera.sessionId.delete(sessionId);
  ctx.db.session.id.delete(sessionId);
});

// Every 10 s: requeue jobs whose worker stopped renewing its lease (the kill-the-worker demo).
export const sweep = spacetimedb.reducer({ onSchedule: sweepTimer }, { timer: sweepTimer.rowType }, ctx => {
  const now = ctx.timestamp.microsSinceUnixEpoch;
  for (const j of [...ctx.db.solveJob.state.filter('running')]) {
    if (!j.leaseUntil || j.leaseUntil.microsSinceUnixEpoch > now) continue;
    const dead = j.attempts >= MAX_ATTEMPTS;
    console.log(`sweep: solve ${j.id} lease expired, ${dead ? 'gave up' : 'requeued'}`);
    ctx.db.solveJob.id.update({ ...j, state: dead ? 'failed' : 'queued', worker: undefined, leaseUntil: undefined,
      progress: dead ? 'gave up after 3 workers stopped' : 'worker stopped; requeued', error: dead ? 'worker lease expired 3 times' : '' });
    notify(ctx, j.sessionId, 'job_reclaimed', dead ? 'Solve gave up' : 'Worker stopped; solve requeued');
  }
  for (const j of [...ctx.db.previewJob.state.filter('running')]) {
    if (!j.leaseUntil || j.leaseUntil.microsSinceUnixEpoch > now) continue;
    // A render's layers lived in the crew's HTTP request, so another worker can't pick it up: it fails.
    const render = j.kind === 'render', dead = render || j.attempts >= MAX_ATTEMPTS;
    ctx.db.previewJob.id.update({ ...j, state: dead ? 'failed' : 'queued', worker: undefined, leaseUntil: undefined,
      error: render ? 'the render worker stopped' : dead ? 'worker lease expired 3 times' : '' });
    if (dead) notify(ctx, j.sessionId, `${j.kind}_failed`, render ? 'The render worker stopped; render again' : 'Preview gave up after 3 workers stopped');
  }
});

// ---------------------------------------------------------------------------------------------------------------
// Presence: heartbeats in, timeouts out.

export const heartbeat = spacetimedb.reducer({ sessionId: t.u64(), focusObjectId: t.u64() }, (ctx, { sessionId, focusObjectId }) => {
  const me = member(ctx, sessionId);
  if (!me) throw new SenderError('join the session first');
  const row = { participantId: me.id, sessionId, identity: ctx.sender, name: me.name, color: colorFor(me.id), status: 'active', focusObjectId, at: ctx.timestamp };
  if (ctx.db.presence.participantId.find(me.id)) ctx.db.presence.participantId.update(row); else ctx.db.presence.insert(row);
});

const IDLE_US = 30_000_000n, GONE_US = 120_000_000n;
// Every 10 s. A tab that froze mid-drag still holds its websocket, so onDisconnect never frees its gizmo lock; this does.
export const presenceSweep = spacetimedb.reducer({ onSchedule: presenceTimer }, { timer: presenceTimer.rowType }, ctx => {
  const now = ctx.timestamp.microsSinceUnixEpoch;
  for (const p of [...ctx.db.presence.iter()]) {
    const age = now - p.at.microsSinceUnixEpoch;
    if (age < IDLE_US) continue;
    if (age >= GONE_US) ctx.db.presence.participantId.delete(p.participantId);
    else if (p.status !== 'idle') ctx.db.presence.participantId.update({ ...p, status: 'idle' });
    for (const o of [...ctx.db.sceneObject.sessionId.filter(p.sessionId)])
      if (o.lockedBy?.equals(p.identity)) {
        console.log(`presence_sweep: ${p.name} silent ${Number(age / 1_000_000n)} s, released object ${o.id}`);
        ctx.db.sceneObject.id.update({ ...o, lockedBy: undefined });
        notify(ctx, p.sessionId, 'lock_released', `${p.name} went quiet; ${o.name || 'an object'} is free to move`);
      }
  }
});

// ---------------------------------------------------------------------------------------------------------------
// Ephemeral set events: cursors, laser-pointer pings, camera views, follow requests. Event table rows reach every
// subscriber in the session once and are never stored.

const SET_EVENT_KINDS = ['cursor', 'ping', 'view', 'follow', 'unfollow'];
// A client sends cursors at 10 Hz and its view at 5 Hz while followed; anything far beyond that is a runaway tab.
const setEventLimit = rateLimit.client({ scope: 'set_event', limit: 40, windowSeconds: 1 });
const pingLimit = rateLimit.client({ scope: 'set_event.ping', limit: 8, windowSeconds: 10 });
export const sendSetEvent = spacetimedb.reducer(
  { sessionId: t.u64(), kind: t.string(), x: t.f64(), y: t.f64(), z: t.f64(), tx: t.f64(), ty: t.f64(), tz: t.f64(), objectId: t.u64(), target: t.option(t.identity()) },
  (ctx, a) => {
    const me = member(ctx, a.sessionId);
    if (!me) throw new SenderError('join the session first');
    if (!SET_EVENT_KINDS.includes(a.kind)) throw new SenderError('unknown set event');
    const key = ctx.sender.toHexString();
    if (!setEventLimit.consume(ctx.as.rateLimit, { key }).allowed) throw new SenderError('set_event.rate_limited');
    if (a.kind === 'ping' && !pingLimit.consume(ctx.as.rateLimit, { key }).allowed) throw new SenderError('set_event.ping_rate_limited');
    finite(a.x, a.y, a.z, a.tx, a.ty, a.tz);
    if ([a.x, a.y, a.tx, a.ty].some(v => Math.abs(v) > 5000) || Math.abs(a.z) > 2000 || Math.abs(a.tz) > 2000) throw new SenderError('point too far from the spot');
    for (const recipient of audience(ctx, a.sessionId))
      ctx.db.setEvent.insert({ ...a, recipient, target: a.target, from: ctx.sender, name: me.name, color: colorFor(me.id) });
  }
);

// ---------------------------------------------------------------------------------------------------------------
// Live sun: a per-session schedule row; while it exists the set's clock (session.planTime) moves every second.

export const setSunClock = spacetimedb.reducer({ sessionId: t.u64(), rate: t.f64() }, (ctx, { sessionId, rate }) => {
  requireMember(ctx, sessionId);
  finite(rate);
  const old = ctx.db.sunClock.sessionId.find(sessionId);
  if (old) ctx.db.sunClock.scheduledId.delete(old.scheduledId);
  if (rate === 0) { trace(ctx, sessionId, 'setSunClock', 'stopped'); return; }
  if (!(rate >= 1 && rate <= 3600)) throw new SenderError('rate must be 1 (live) to 3600');
  const s = ctx.db.session.id.find(sessionId)!;
  if (rate === 1 || !s.planTime) ctx.db.session.id.update({ ...s, planTime: ctx.timestamp });
  ctx.db.sunClock.insert({ scheduledId: 0n, scheduledAt: ScheduleAt.interval(1_000_000n), sessionId, rate, startedBy: whoName(ctx, sessionId) });
  trace(ctx, sessionId, 'setSunClock', rate === 1 ? 'live' : `${rate}x`);
});

export const sunTick = spacetimedb.reducer({ onSchedule: sunClock }, { clock: sunClock.rowType }, (ctx, { clock }) => {
  const s = ctx.db.session.id.find(clock.sessionId);
  if (!s) { ctx.db.sunClock.scheduledId.delete(clock.scheduledId); return; }
  const at = clock.rate === 1 || !s.planTime
    ? ctx.timestamp
    : new Timestamp(s.planTime.microsSinceUnixEpoch + BigInt(Math.round(clock.rate * 1_000_000)));
  ctx.db.session.id.update({ ...s, planTime: at });
});

// ---------------------------------------------------------------------------------------------------------------
// Sharing a finished shot: a public share code, the row goes to shotmatch-library through the outbox, and the
// onResult reducer marks it published. GET /shot?code=<share code> serves it as JSON.

const shareCode = (ctx: Ctx) => {
  for (;;) {
    let c = '';
    for (let i = 0; i < 8; i++) c += CODE_CHARS[ctx.random.integerInRange(0, CODE_CHARS.length - 1)];
    if (!ctx.db.publicShot.shareCode.find(c) && !ctx.db.session.code.find(c)) return c;
  }
};

export const shareShot = spacetimedb.reducer({ sessionId: t.u64(), previewJobId: t.u64() }, (ctx, { sessionId, previewJobId }) => {
  requireMember(ctx, sessionId);
  const j = ctx.db.previewJob.id.find(previewJobId);
  if (!j || j.sessionId !== sessionId || j.state !== 'done' || !j.imageUrl) throw new SenderError('pick a finished preview or render');
  const link = ctx.db.libraryLink.id.find(0);
  if (!link) throw new SenderError('the shared library is not linked yet');
  const s = ctx.db.session.id.find(sessionId)!;
  const pose = ctx.db.camera.sessionId.find(sessionId)?.pose ?? ctx.db.solveResult.photoId.find(j.photoId)?.pose;
  if (!pose) throw new SenderError('place the camera first');
  const row = {
    shareCode: shareCode(ctx), title: s.title.startsWith('photon:') ? 'Tessera plan' : s.title, spotId: s.spotId, imageUrl: absUrl(ctx, j.imageUrl),
    lat: pose.lat, lon: pose.lon, heading: pose.heading, pitch: pose.pitch, f35: pose.f35,
  };
  ctx.db.publicShot.insert({ ...row, sessionId, state: 'pending', error: '', createdAt: ctx.timestamp });
  ctx.db.publishShotOutbox.insert({ ...row, msgId: 0n, target: link.db, sessionId });
  trace(ctx, sessionId, 'shareShot', row.shareCode);
});

export const onPublishShot = spacetimedb.reducer(
  { onResult: publishShotOutbox },
  { row: publishShotOutbox.rowType, result: t.result(t.unit(), t.string()) },
  (ctx, { row, result }) => {
    const p = ctx.db.publicShot.shareCode.find(row.shareCode);
    const err = 'err' in result ? result.err : '';
    console.log(`idc publish_shot ${row.shareCode} -> shotmatch-library: ${err || 'ok'}`);
    if (p) ctx.db.publicShot.shareCode.update({ ...p, state: err ? 'failed' : 'published', error: err });
    notify(ctx, row.sessionId, err ? 'share_failed' : 'shot_shared', err ? `Sharing failed: ${err}` : `Shared as ${row.shareCode}`);
    traceAs(ctx, row.sessionId, 'onPublishShot', 'shotmatch-library', err || `published ${row.shareCode}`);
  }
);

export const onPublishProp = spacetimedb.reducer(
  { onResult: publishPropOutbox },
  { row: publishPropOutbox.rowType, result: t.result(t.unit(), t.string()) },
  (ctx, { row, result }) => {
    const err = 'err' in result ? result.err : '';
    console.log(`idc publish_prop "${row.name}" -> shotmatch-library: ${err || 'ok'}`);
    if (!err && !ctx.db.libraryProp.assetUrl.find(row.assetUrl))
      ctx.db.libraryProp.insert({ assetUrl: row.assetUrl, name: row.name, prompt: row.prompt, fromSessionId: row.sessionId, publishedAt: ctx.timestamp });
    notify(ctx, row.sessionId, err ? 'library_failed' : 'prop_shared', err ? `Library refused the prop: ${err}` : `${row.name || 'Prop'} is now in every session's library`);
    traceAs(ctx, row.sessionId, 'onPublishProp', 'shotmatch-library', err || row.name);
  }
);

// ---------------------------------------------------------------------------------------------------------------
// Procedure with outbound HTTP: Nemotron 3.5 Lightning names a shoot once its photo is placed. Scheduled by finishJob,
// so no worker process is involved: the database calls NVIDIA itself and writes the title in a transaction.

const LIGHTNING = 'nvidia/nemotron-3.5-lightning-30b-a3b';
const compass = (deg: number) => ['north', 'northeast', 'east', 'southeast', 'south', 'southwest', 'west', 'northwest'][Math.round((((deg % 360) + 360) % 360) / 45) % 8];

export const titleSession = spacetimedb.procedure({ onSchedule: titleJob }, { job: titleJob.rowType }, t.unit(), (ctx, { job }) => {
  const key = ctx.env.NVIDIA_API_KEY;
  const facts = ctx.withTx(tx => {
    const s = tx.db.session.id.find(job.sessionId);
    if (!s || !UNTITLED.has(s.title)) return null;
    const spot = tx.db.spot.id.find(s.spotId);
    const pose = tx.db.camera.sessionId.find(s.id)?.pose;
    const people = [...tx.db.person.sessionId.filter(s.id)].length;
    const words = [...tx.db.message.sessionId.filter(s.id)].filter(m => m.direction === 'in').map(m => m.text).join(' ').slice(0, 300);
    return [
      `Spot: ${spot?.name ?? s.spotId ?? 'unknown'}.`,
      pose ? `Lens: about ${Math.round(pose.f35)} mm (35 mm equivalent). Camera faces ${compass(pose.heading)}.` : '',
      s.planTime ? `Planned for ${s.planTime.toDate().toISOString().slice(0, 16)} UTC.` : '',
      people ? `${people} people in the shot.` : '',
      words ? `What the group said: ${words}` : '',
    ].filter(Boolean).join(' ');
  });
  if (!facts) return {};
  let title = '', error = '';
  const t0 = Date.now();
  if (!key) error = 'NVIDIA_API_KEY is not set in the database environment';
  else {
    try {
      const r = ctx.http.fetch('https://integrate.api.nvidia.com/v1/chat/completions', {
        method: 'POST',
        headers: { authorization: `Bearer ${key}`, 'content-type': 'application/json' },
        body: JSON.stringify({
          model: LIGHTNING, max_tokens: 24, temperature: 0.4, chat_template_kwargs: { enable_thinking: false },
          messages: [
            { role: 'system', content: 'You name photo shoots. Reply with one title of 2 to 6 words. No quotes, no emoji, no final punctuation.' },
            { role: 'user', content: facts },
          ],
        }),
        timeout: TimeDuration.fromMillis(15_000),
      });
      if (!r.ok) error = `HTTP ${r.status} ${r.text().slice(0, 120)}`;
      else title = String(r.json()?.choices?.[0]?.message?.content ?? '').replace(/["“”*#]/g, '').split('\n')[0].trim().slice(0, 60);
    } catch (e) { error = String(e).slice(0, 200); }
  }
  const ms = Date.now() - t0;
  console.log(`title_session ${job.sessionId}: ${title ? `"${title}"` : `error ${error}`} (${LIGHTNING}, ${ms} ms)`);
  ctx.withTx(tx => {
    const s = tx.db.session.id.find(job.sessionId);
    if (!s) return;
    tx.db.agentStep.insert({ id: 0n, sessionId: s.id, tool: 'nemotron_lightning.title_session', args: facts, result: title ? `"${title}"` : `error: ${error || 'empty reply'}`, ms: Math.max(0, ms), at: tx.timestamp });
    traceAs(tx, s.id, 'titleSession', 'Nemotron 3.5 Lightning', title || error);
    if (title && UNTITLED.has(s.title)) {
      tx.db.session.id.update({ ...s, title });
      notify(tx, s.id, 'titled', `Nemotron named this shoot "${title}"`);
    }
  });
  return {};
});

// ---------------------------------------------------------------------------------------------------------------
// Geo layers: a scheduled procedure fetches weather (Open-Meteo) and NWS alerts for active spots every 15 minutes,
// straight from the database; sessions toggle which layers they show.

const LAYERS = ['weather', 'alerts', 'quakes', 'film', 'closures', 'construction', 'tides', 'buildings', 'shadow', 'pois', 'photographers', 'moon'];
export const setLayerToggle = spacetimedb.reducer({ sessionId: t.u64(), layer: t.string(), on: t.bool() }, (ctx, { sessionId, layer, on }) => {
  requireMember(ctx, sessionId);
  if (!LAYERS.includes(layer)) throw new SenderError('unknown layer');
  const old = [...ctx.db.layerToggle.sessionId.filter(sessionId)].find(r => r.layer === layer);
  if (old) ctx.db.layerToggle.id.update({ ...old, on, updatedBy: ctx.sender, updatedAt: ctx.timestamp });
  else ctx.db.layerToggle.insert({ id: 0n, sessionId, layer, on, updatedBy: ctx.sender, updatedAt: ctx.timestamp });
  trace(ctx, sessionId, 'setLayerToggle', `${layer} ${on ? 'on' : 'off'}`);
});

const ACTIVE_US = 2n * 3600n * 1_000_000n;
const HOURLY = 'cloud_cover_low,cloud_cover_mid,cloud_cover_high,visibility,precipitation_probability,wind_speed_10m,temperature_2m,relative_humidity_2m';
const fetchLayer = (ctx: { http: { fetch: (u: string, i?: any) => any } }, layer: string, lat: number, lon: number): string => {
  if (layer === 'weather') {
    const url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&hourly=${HOURLY}&wind_speed_unit=mph&temperature_unit=fahrenheit&timezone=GMT&forecast_days=2`;
    const r = ctx.http.fetch(url, { timeout: TimeDuration.fromMillis(15_000) });
    if (!r.ok) throw new Error(`Open-Meteo HTTP ${r.status}`);
    const hourly = r.json()?.hourly;
    if (!hourly) throw new Error('Open-Meteo reply had no hourly data');
    return JSON.stringify(hourly);
  }
  const r = ctx.http.fetch(`https://api.weather.gov/alerts/active?point=${lat.toFixed(4)},${lon.toFixed(4)}`, {
    headers: { 'User-Agent': 'Tessera (me@thebenzhou.com)', Accept: 'application/geo+json' }, timeout: TimeDuration.fromMillis(15_000),
  });
  if (!r.ok) throw new Error(`weather.gov HTTP ${r.status}`);
  const features: any[] = r.json()?.features ?? [];
  const alerts = features.map(f => f?.properties ?? {}).map(p => ({ event: p.event ?? '', severity: p.severity ?? '', headline: p.headline ?? '', onset: p.onset ?? '', ends: p.ends ?? '', areaDesc: p.areaDesc ?? '' }));
  return JSON.stringify({ count: alerts.length, alerts });
};

export const refreshLayers = spacetimedb.procedure({ onSchedule: layerTimer }, { timer: layerTimer.rowType }, t.unit(), ctx => {
  // Active spots: sessions with presence now or a scene edit in the last 2 hours, plus nyc_dumbo.
  const spots = ctx.withTx(tx => {
    const since = tx.timestamp.microsSinceUnixEpoch - ACTIVE_US;
    const sessions = new Set<bigint>([...tx.db.presence.iter()].map(p => p.sessionId));
    for (const c of tx.db.sceneChange.iter()) if (c.at.microsSinceUnixEpoch >= since) sessions.add(c.sessionId);
    const bySpot = new Map<string, bigint[]>([['nyc_dumbo', []]]);
    for (const id of sessions) {
      const spotId = tx.db.session.id.find(id)?.spotId;
      if (spotId) bySpot.set(spotId, [...(bySpot.get(spotId) ?? []), id]);
    }
    return [...bySpot].flatMap(([spotId, sessionIds]) => {
      const sp = tx.db.spot.id.find(spotId);
      return sp ? [{ spotId, lat: sp.lat, lon: sp.lon, sessionIds }] : [];
    });
  });
  for (const sp of spots) for (const layer of ['weather', 'alerts']) {
    const t0 = Date.now();
    let summary = '', error = '';
    try { summary = fetchLayer(ctx, layer, sp.lat, sp.lon); } catch (e) { error = String((e as Error)?.message ?? e).slice(0, 300); }
    const ms = Date.now() - t0;
    console.log(`refresh_layers ${layer} ${sp.spotId}: ${error || 'ok'} (${ms} ms)`);
    ctx.withTx(tx => {
      const old = [...tx.db.layerSnapshot.spotId.filter(sp.spotId)].find(r => r.layer === layer);
      const row = { spotId: sp.spotId, layer, geojsonUrl: `/api/layers?spot=${sp.spotId}&layers=${layer}`, error };
      if (old) tx.db.layerSnapshot.id.update({ ...old, ...row, ...(error ? {} : { summary, fetchedAt: tx.timestamp }) });
      else tx.db.layerSnapshot.insert({ id: 0n, ...row, summary, fetchedAt: tx.timestamp });
      for (const sid of sp.sessionIds)
        traceAs(tx, sid, 'refreshLayers', 'procedure', error ? `${layer} for ${sp.spotId} failed: ${error}` : `refreshed ${layer} for ${sp.spotId} in ${ms} ms`);
    });
  }
  return {};
});

// ---------------------------------------------------------------------------------------------------------------
// Views. Per-user views read ctx.sender; anonymous views are computed once and shared by every subscriber.

// Per-user: the sessions I'm in (the home page's "Your shoots"). Query-builder semijoin, evaluated incrementally.
export const mySessions = spacetimedb.view({ name: 'my_sessions', public: true }, t.array(session.rowType),
  ctx => ctx.from.participant.where(p => p.identity.eq(ctx.sender)).rightSemijoin(ctx.from.session, (p, s) => p.sessionId.eq(s.id)));

// Per-user: the objects whose gizmo I hold, in any session.
export const mySceneLocks = spacetimedb.view({ name: 'my_scene_locks', public: true }, t.array(sceneObject.rowType), ctx => {
  const out = [];
  for (const p of ctx.db.participant.identity.filter(ctx.sender))
    for (const o of ctx.db.sceneObject.sessionId.filter(p.sessionId)) if (o.lockedBy?.equals(ctx.sender)) out.push(o);
  return out;
});

const SessionCard = t.row('SessionCardRow', { id: t.u64(), code: t.string(), title: t.string(), spotId: t.string(), online: t.u32(), objects: t.u32() });
// Anonymous, with an argument: whoever knows a code can see that one session's card and join. Session rows themselves
// are visible only to participants (the filters below), so the code is the capability.
export const sessionCard = spacetimedb.anonymousView({ name: 'session_card', public: true }, { code: t.string() }, t.array(SessionCard), (ctx, { code }) => {
  const s = ctx.db.session.code.find(code.trim().toUpperCase());
  if (!s) return [];
  const online = [...ctx.db.participant.sessionId.filter(s.id)].filter(p => p.online).length;
  return [{ id: s.id, code: s.code, title: s.title, spotId: s.spotId, online, objects: [...ctx.db.sceneObject.sessionId.filter(s.id)].length }];
});

const LiveSession = t.row('LiveSessionRow', { sessionId: t.u64().primaryKey(), spotId: t.string(), online: t.u32(), planners: t.u32(), scouts: t.u32(), objects: t.u32() });
// Anonymous: sessions with someone connected right now, with counts. No codes or titles, so nothing private leaks.
export const liveSessions = spacetimedb.anonymousView({ name: 'live_sessions', public: true }, t.array(LiveSession), ctx => {
  const by = new Map<bigint, { online: number; planners: number; scouts: number }>();
  for (const p of ctx.db.participant.by_online.filter(true)) {
    if (p.role === 'crew') continue;
    const c = by.get(p.sessionId) ?? { online: 0, planners: 0, scouts: 0 };
    c.online++; if (p.role === 'scout') c.scouts++; else c.planners++;
    by.set(p.sessionId, c);
  }
  return [...by].flatMap(([sessionId, c]) => {
    const s = ctx.db.session.id.find(sessionId);
    return s ? [{ sessionId, spotId: s.spotId, ...c, objects: [...ctx.db.sceneObject.sessionId.filter(sessionId)].length }] : [];
  });
});

// Anonymous query-builder views over the shared library and the spots that have a 3D model.
export const spotLibrary = spacetimedb.anonymousView({ name: 'spot_library', public: true }, t.array(spot.rowType),
  ctx => ctx.from.spot.where(s => s.cameras.gt(0)));
export const shotLibrary = spacetimedb.anonymousView({ name: 'shot_library', public: true }, t.array(publicShot.rowType),
  ctx => ctx.from.publicShot.where(s => s.state.eq('published')));
export const propLibrary = spacetimedb.anonymousView({ name: 'prop_library', public: true }, t.array(libraryProp.rowType),
  ctx => ctx.from.libraryProp);

// ---------------------------------------------------------------------------------------------------------------
// Row-level security (client visibility filters). Every session-scoped row is visible only to that session's
// participants and the crew identity; spots and the library views stay public. Filters are OR-ed per table.

const SESSION_TABLES = [
  'participant', 'photo', 'solve_job', 'solve_result', 'camera', 'person', 'device_pose', 'preview_job', 'message', 'agent_step',
  'reminder', 'outbox', 'shot_settings', 'scene_object', 'presence', 'scene_change', 'sun_clock', 'channel_link', 'shot_version', 'checkin',
  'layer_toggle',
];
const EVENT_TABLES = ['toast', 'set_event', 'activity'];
const member_sql = (tb: string, col = 'session_id') =>
  `SELECT ${tb}.* FROM ${tb} JOIN session_member ON ${tb}.${col} = session_member.session_id WHERE session_member.identity = :sender`;
export const visibility = spacetimedb.exportGroup({
  rls_session: spacetimedb.clientVisibilityFilter.sql(member_sql('session', 'id')),
  ...Object.fromEntries(SESSION_TABLES.map(tb => [`rls_${tb}`, spacetimedb.clientVisibilityFilter.sql(member_sql(tb))])),
  ...Object.fromEntries(EVENT_TABLES.map(tb => [`rls_${tb}`, spacetimedb.clientVisibilityFilter.sql(`SELECT * FROM ${tb} WHERE ${tb}.recipient = :sender`)])),
});

// ---------------------------------------------------------------------------------------------------------------
// HTTP handlers, served at https://maincloud.spacetimedb.com/v1/database/shotmatch/route/<path>.

const json = (v: unknown, status = 200) => new SyncResponse(
  JSON.stringify(v, (_k, x) => (typeof x === 'bigint' ? x.toString() : x)),
  { status, headers: { 'content-type': 'application/json; charset=utf-8', 'access-control-allow-origin': '*', 'cache-control': 'no-store' } },
);

export const health = spacetimedb.httpHandler((ctx, _req) => ctx.withTx(tx => json({
  ok: true, database: ctx.identity.toHexString(), at: tx.timestamp.toDate().toISOString(),
  sessions: Number(tx.db.session.count()), sceneObjects: Number(tx.db.sceneObject.count()),
  online: [...tx.db.participant.by_online.filter(true)].length, sceneChanges: Number(tx.db.sceneChange.count()),
  libraryLinked: !!tx.db.libraryLink.id.find(0), sharedProps: Number(tx.db.libraryProp.count()),
})));

// Strict routing has no path parameters, so the share link is /shot?code=<share code>.
export const shotJson = spacetimedb.httpHandler((ctx, req) => {
  const code = (/[?&]code=([A-Za-z0-9]{4,16})/.exec(req.uri)?.[1] ?? '').toUpperCase();
  if (!code) return json({ error: 'add ?code=<share code>' }, 400);
  return ctx.withTx(tx => {
    const s = tx.db.publicShot.shareCode.find(code);
    if (!s || s.state !== 'published') return json({ error: 'no published shot with that code' }, 404);
    const spot = tx.db.spot.id.find(s.spotId);
    return json({
      shareCode: s.shareCode, title: s.title, imageUrl: s.imageUrl, label: 'AI interpretation',
      spot: spot ? { id: spot.id, name: spot.name, lat: spot.lat, lon: spot.lon } : { id: s.spotId },
      camera: { lat: s.lat, lon: s.lon, headingDeg: s.heading, pitchDeg: s.pitch, f35mm: s.f35 },
      publishedAt: s.createdAt.toDate().toISOString(),
    });
  });
});

// ElevenLabs post-call webhook: checks the HMAC signature inside the database, then writes the call's transcript into
// the session's messages. The session comes from the agent's session_code or session_id dynamic variable, else from the
// caller's phone number matched against channel_link (the newest link wins).
const digits = (s: string) => s.replace(/\D/g, '').replace(/^1(?=\d{10}$)/, '');
export const elevenlabsWebhook = spacetimedb.httpHandler((ctx, req) => {
  const key = ctx.env.ELEVENLABS_WEBHOOK_SECRET;
  if (!key) return json({ error: 'webhook secret not configured' }, 503);
  const body = req.bytes();
  const now = Number(ctx.timestamp.microsSinceUnixEpoch / 1_000_000n);
  if (!verifyElevenLabs(req.headers.get('elevenlabs-signature'), body, key, now)) return json({ error: 'bad signature' }, 401);
  let ev: any;
  try { ev = JSON.parse(new TextDecoder().decode(body)); } catch { return json({ error: 'body is not JSON' }, 400); }
  if (ev?.type !== 'post_call_transcription') return json({ ok: true, ignored: String(ev?.type ?? '') });
  const d = ev.data ?? {};
  const conversationId = String(d.conversation_id ?? '').slice(0, 120);
  if (!conversationId) return json({ error: 'no conversation_id' }, 400);
  const vars = d.conversation_initiation_client_data?.dynamic_variables ?? {};
  const turns: { role: string; message: string }[] = (Array.isArray(d.transcript) ? d.transcript : []).filter((x: any) => typeof x?.message === 'string' && x.message);
  return ctx.withTx(tx => {
    if (tx.db.voiceCall.conversationId.find(conversationId)) return json({ ok: true, duplicate: true });
    console.log(`POST /hooks/elevenlabs: signature ok, conversation ${conversationId}, ${turns.length} turns`);
    const code = String(vars.session_code ?? '').trim().toUpperCase();
    const caller = digits(String(vars.system__caller_id ?? d.metadata?.phone_call?.external_number ?? ''));
    const byPhone = caller.length >= 7
      ? [...tx.db.channelLink.iter()].filter(l => digits(l.address) === caller).sort((a, b) => Number(b.id - a.id))[0]
      : undefined;
    const s = (code && tx.db.session.code.find(code)) || (/^\d+$/.test(String(vars.session_id ?? '')) ? tx.db.session.id.find(BigInt(vars.session_id)) : undefined)
      || (byPhone ? tx.db.session.id.find(byPhone.sessionId) : undefined);
    const summary = String(d.analysis?.transcript_summary ?? '').slice(0, 1000);
    tx.db.voiceCall.insert({ conversationId, sessionId: s?.id ?? 0n, turns: turns.length, durationS: Number(d.metadata?.call_duration_secs ?? 0) || 0, summary, at: tx.timestamp });
    if (s) {
      for (const [i, m] of turns.slice(0, 200).entries())
        tx.db.message.insert({
          id: 0n, sessionId: s.id, channel: 'voice', threadId: conversationId, externalId: `${conversationId}:${i}`, parentExternalId: '',
          direction: m.role === 'agent' ? 'out' : 'in', author: m.role === 'agent' ? 'Tessera guide' : 'Caller', text: m.message.slice(0, 4000), imageUrl: '', createdAt: tx.timestamp,
        });
      notify(tx, s.id, 'voice_call', `Phone call saved: ${turns.length} turns`);
      traceAs(tx, s.id, 'POST /hooks/elevenlabs', 'ElevenLabs', `${turns.length} turns`);
    }
    return json({ ok: true, session: s?.code ?? null, turns: turns.length });
  });
});

export const router = spacetimedb.httpRouter(
  new Router()
    .get('/health', health)
    .get('/shot', shotJson)
    .post('/hooks/elevenlabs', elevenlabsWebhook)
);
